/* ============================================================================
 * TapMyCar  Patch  Pricing copy + $14.99 upgrade + Business page + Landing additions
 *
 * 1) pricing.html  Premium tagline + bullets rewritten (no "reinforced
 *    backing"; 3 stickers framing). Standard bullets gain emergency contact.
 *    Business button now points to /business.html.
 * 2) api/create-checkout.js  Standard->Premium upgrade flow now charges
 *    a flat $14.99 single line item.
 * 3) manage.html  Upgrade button now shows a confirmation modal first.
 * 4) help.html  FAQ "Can I upgrade?" updated with the new $14.99 price.
 * 5) landing.html  Two new sections after Solution: harassment protection
 *    + tow operator partnership.
 * 6) NEW public/business.html  bulk/fleet form with logo upload.
 * 7) NEW api/business-inquiry.js  uploads logo + emails support + persists.
 *
 * Run from project root:  node tapmycar-patch-content-upgrade-business.js
 * BEFORE FIRST RUN: apply patch-business-leads-migration.sql in Supabase.
 * Safe to re-run.
 * ==========================================================================*/
'use strict';
const fs = require('fs');
const path = require('path');

const STAMP = new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-');
const BACKUP_DIR = 'backup-content-upgrade-business-' + STAMP;

const FILES = {"public/pricing.html": "<!-- TMC_PATCH36B_CANCEL_WORDING -->\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <link rel=\"manifest\" href=\"/manifest.json\">\n  <meta name=\"theme-color\" content=\"#FF6B00\">\n  <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0\">\n  <title>Pricing — Free, Standard, Premium plans | TapMyCar</title>\n  <link rel=\"stylesheet\" href=\"/app.css\">\n<link rel=\"stylesheet\" href=\"/tmc-redesign.css\">\n  <style>\n    .plan-card{border:1.5px solid var(--bd);border-radius:18px;padding:18px;background:#fff;margin-bottom:12px;position:relative}\n    .plan-card.hero{border:2.5px solid var(--or)}\n    .plan-card.ghost{border:1.5px solid #E5E7EB;background:#F9FAFB}\n    .hero-badge{position:absolute;top:-12px;left:50%;transform:translateX(-50%);background:var(--or);color:#fff;font-size:11px;font-weight:700;padding:4px 16px;border-radius:99px;white-space:nowrap}\n    .plan-top{display:flex;align-items:baseline;gap:8px;margin-bottom:6px;margin-top:6px}\n    .plan-name{font-size:20px;font-weight:800;color:var(--bk)}\n    .plan-name.ghost{font-size:17px;font-weight:700;color:var(--gy)}\n    .plan-price{font-size:22px;font-weight:800;color:var(--or)}\n    .plan-sub{font-size:12px;color:var(--gy)}\n    .plan-tagline{font-size:12px;color:var(--gy);margin-bottom:14px}\n    .bullets{display:flex;flex-direction:column;gap:6px;margin-bottom:14px}\n    .bullet{font-size:12px;color:var(--bk);display:flex;gap:8px;align-items:flex-start;line-height:1.5}\n    .bullet-dot{width:6px;height:6px;border-radius:1px;background:var(--or);flex-shrink:0;margin-top:7px}\n    .bullet.mute{color:#9CA3AF}\n    .bullet.mute .bullet-dot{background:#D1D5DB}\n    .prepay-row{display:flex;align-items:center;gap:10px;background:#FFF7ED;border:1px solid #FFE4CC;border-radius:10px;padding:10px 12px;margin-bottom:12px;cursor:pointer;user-select:none}\n    .prepay-row:hover{background:#FFF3EC}\n    .prepay-check{width:20px;height:20px;border:1.5px solid #FED7AA;border-radius:5px;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#fff;transition:all .15s}\n    .prepay-row.on .prepay-check{background:var(--or);border-color:var(--or)}\n    .prepay-row.on .prepay-check::after{content:'';width:10px;height:10px;background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='3' stroke-linecap='round'><polyline points='20 6 9 17 4 12'/></svg>\");background-repeat:no-repeat;background-size:contain}\n    .prepay-label{font-size:12px;color:#9A3412;line-height:1.4}\n    .prepay-label b{color:#7C2D12;font-weight:700}\n    .disclosure{font-size:10px;color:#9CA3AF;text-align:center;margin-top:8px;line-height:1.5;padding:0 4px}\n    .disclosure a{color:var(--or);text-decoration:none;font-weight:600}\n    .btn-err{background:#FEE2E2;color:#DC2626;font-size:11px;padding:8px 12px;border-radius:8px;margin-top:8px;text-align:center;display:none}\n    .btn-err.show{display:block}\n  </style>\n<!-- Favicon -->\n<link rel=\"icon\" type=\"image/x-icon\" href=\"/favicon.ico\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<!-- SEO -->\n<meta name=\"description\" content=\"Simple pricing for TapMyCar. Free eTag, $9.99 Standard sticker, $24.99 Premium with 3 stickers for family. No hidden fees.\">\n<meta name=\"author\" content=\"Praman Tech LLC\">\n<!-- Open Graph -->\n<meta property=\"og:title\" content=\"Pricing — Free, Standard, Premium plans | TapMyCar\">\n<meta property=\"og:description\" content=\"Simple pricing for TapMyCar. Free eTag, $9.99 Standard sticker, $24.99 Premium with 3 stickers for family. No hidden fees.\">\n<meta property=\"og:image\" content=\"https://tapmycar.io/og-image.png\">\n<meta property=\"og:url\" content=\"https://tapmycar.io/pricing.html\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"TapMyCar\">\n<!-- Twitter Card -->\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Pricing — Free, Standard, Premium plans | TapMyCar\">\n<meta name=\"twitter:description\" content=\"Simple pricing for TapMyCar. Free eTag, $9.99 Standard sticker, $24.99 Premium with 3 stickers for family. No hidden fees.\">\n<meta name=\"twitter:image\" content=\"https://tapmycar.io/og-image.png\">\n<script>\n/* TMC_PATCH45B_FIX: pricing-page referral-credit banner + apply checkbox.\n   Fetches the user's available credit on load. If > 0, inserts a banner\n   into its OWN strip below the header (not into the header itself).\n   Checkbox is default UNCHECKED  user has to opt in to applying credit.\n   The pre-existing 'discount-banner' is also tied to this checkbox: when\n   the user ticks the box we show it; when unticked we hide it, so both\n   banners reflect the same intent. */\n(function () {\n  /* TMC_PATCH45C_PRICING_V2: dynamic per-plan price/button/note updates\n     with a re-entry guard. v1 had infinite recursion between\n     updateCreditDisplay() and our wrapped updateButtonLabels(); v2 fixes\n     it with window.__tmcUpdating, and never calls updateButtonLabels()\n     from updateCreditDisplay() (restore path uses the cached originals). */\n  window.__tmcCreditDollars = 0;\n  window.__tmcUpdating = false;\n\n  function setApplied(on, dollars) {\n    try {\n      window.__refDiscount = on ? (dollars || 0) : 0;\n      window.__tmcApply = !!on;\n      if (typeof dollars === 'number') window.__tmcCreditDollars = dollars;\n      var legacy = document.getElementById('discount-banner');\n      if (legacy) legacy.style.display = on ? 'block' : 'none';\n      updateCreditDisplay();\n    } catch (e) {}\n  }\n\n  function updateCreditDisplay() {\n    if (window.__tmcUpdating) return; /* guard against re-entry */\n    window.__tmcUpdating = true;\n    try {\n      var apply = !!window.__tmcApply;\n      var creditCents = Math.round((window.__tmcCreditDollars || 0) * 100);\n      ['standard','premium'].forEach(function (plan) {\n        var prefix = plan === 'standard' ? 'std' : 'prem';\n        var priceEl  = document.getElementById(prefix + '-price');\n        var btnAmtEl = document.getElementById(prefix + '-btn-amt');\n        var btnEl    = document.getElementById(prefix + '-btn');\n        if (!priceEl || !btnAmtEl || !btnEl) return;\n\n        /* Save the originals once so we can restore them on untick. */\n        if (typeof priceEl.dataset.tmcOriginal === 'undefined') {\n          priceEl.dataset.tmcOriginal = priceEl.innerHTML;\n        }\n        /* btnAmtEl is rewritten by the page's updateButtonLabels() on prepay\n           toggle. We read its CURRENT text to know the prepay-aware base\n           price, then either keep it (untick) or override it (tick). */\n        var btnText = (btnAmtEl.textContent || '').trim();\n        var todayMatch = btnText.match(/\\$([0-9]+(?:\\.[0-9]+)?)/);\n        if (!todayMatch) return;\n        var todayDollars = parseFloat(todayMatch[1]);\n        var todayCents = Math.round(todayDollars * 100);\n\n        var noteId = prefix + '-credit-note';\n        var noteEl = document.getElementById(noteId);\n\n        if (!apply || creditCents <= 0) {\n          /* Restore the price card to its original. Leave btnAmtEl alone\n             because the page's own updateButtonLabels() owns it. Hide the\n             credit note if present. NO cross-function call here  this is\n             what fixes the v1 recursion. */\n          priceEl.innerHTML = priceEl.dataset.tmcOriginal;\n          if (noteEl) noteEl.style.display = 'none';\n          return;\n        }\n\n        /* $1 minimum for direct flow (server-side enforced). */\n        var maxApplyCents = Math.max(0, todayCents - 100);\n        var discountCents = Math.min(creditCents, maxApplyCents);\n        if (discountCents <= 0) {\n          if (noteEl) noteEl.style.display = 'none';\n          return;\n        }\n\n        var finalCents     = todayCents - discountCents;\n        var finalDollars   = (finalCents     / 100).toFixed(2);\n        var discountDollars= (discountCents  / 100).toFixed(2);\n        var remainingCents = creditCents - discountCents;\n        var remainingDolls = (remainingCents / 100).toFixed(2);\n\n        /* Update the on-card price. Preserve the '/yr' sub-span. */\n        var orig = priceEl.dataset.tmcOriginal;\n        var subMatch = orig.match(/<span[\\s\\S]*?<\\/span>/i);\n        var subSpan = subMatch ? subMatch[0] : '';\n        priceEl.innerHTML = '$' + finalDollars + ' ' + subSpan;\n\n        btnAmtEl.textContent = '$' + finalDollars;\n\n        if (!noteEl) {\n          noteEl = document.createElement('div');\n          noteEl.id = noteId;\n          noteEl.style.cssText = 'background:#F0FDF4;border-left:3px solid #16A34A;padding:10px 12px;margin:10px 0 0;font-size:11px;color:#166534;line-height:1.55;border-radius:8px';\n          var parent = btnEl.parentNode;\n          if (parent) parent.insertBefore(noteEl, btnEl.nextSibling);\n        }\n        noteEl.style.display = 'block';\n        if (remainingCents > 0) {\n          noteEl.textContent =\n            '$' + discountDollars + ' applied. $' + finalDollars +\n            ' minimum charge today (saves your card for annual renewal as we accept autopay). $' +\n            remainingDolls + ' remains in your account, can use for future transactions.';\n        } else {\n          noteEl.textContent = '$' + discountDollars + ' referral credit applied.';\n        }\n      });\n    } finally {\n      window.__tmcUpdating = false;\n    }\n  }\n\n  /* Wrap the page's own updateButtonLabels so OUR display refreshes any\n     time a prepay checkbox toggles. The guard prevents recursion: if\n     updateCreditDisplay() is currently running, the wrapper just calls\n     the original and returns without re-triggering our logic. */\n  function hookUpdateButtonLabels() {\n    if (window.__tmcUblHooked) return;\n    if (typeof window.updateButtonLabels !== 'function') return;\n    window.__tmcUblHooked = true;\n    var orig = window.updateButtonLabels;\n    window.updateButtonLabels = function () {\n      try { orig.apply(this, arguments); } catch (e) {}\n      if (!window.__tmcUpdating) {\n        try { updateCreditDisplay(); } catch (e) {}\n      }\n    };\n  }\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', function () {\n      hookUpdateButtonLabels();\n      setTimeout(hookUpdateButtonLabels, 50);\n      setTimeout(hookUpdateButtonLabels, 200);\n      setTimeout(updateCreditDisplay, 250);\n    });\n  } else {\n    hookUpdateButtonLabels();\n    setTimeout(hookUpdateButtonLabels, 50);\n    setTimeout(updateCreditDisplay, 100);\n  }\n  function inject(creditDollars) {\n    if (creditDollars <= 0) return;\n    /* Place the banner in its own dedicated strip between the header\n       and the main content. Anchor: find an element whose next sibling\n       is the 'Simple pricing' heading, OR fall back to the main wrap. */\n    var bar = document.createElement('div');\n    bar.id = 'tmc-refbar';\n    bar.style.cssText = 'background:linear-gradient(90deg,#DCFCE7,#BBF7D0);border:1px solid #86EFAC;border-radius:12px;padding:12px 14px;margin:8px 16px 12px;font-family:Inter,system-ui,sans-serif';\n    bar.innerHTML =\n        '<div style=\"font-size:13px;font-weight:800;color:#166534\">You have $' + creditDollars.toFixed(2) + ' in referral credit</div>' +\n        '<label style=\"display:flex;align-items:center;gap:8px;margin-top:8px;font-size:12px;color:#15803D;font-weight:600;cursor:pointer;user-select:none\">' +\n          '<input type=\"checkbox\" id=\"tmc-apply-credit\" style=\"width:16px;height:16px;cursor:pointer;accent-color:#16A34A\">' +\n          'Tick to apply $' + creditDollars.toFixed(2) + ' discount to your purchase' +\n        '</label>';\n    /* Find a good place: AFTER the header strip, BEFORE the main pricing\n       cards. The discount-banner div (id='discount-banner') is a great\n       anchor  it lives exactly where we want to be. */\n    var legacy = document.getElementById('discount-banner');\n    if (legacy && legacy.parentNode) {\n      legacy.parentNode.insertBefore(bar, legacy);\n    } else {\n      var mainEl = document.querySelector('main') || document.body;\n      mainEl.insertBefore(bar, mainEl.firstChild);\n    }\n    /* Hook the checkbox: when ticked, show the legacy banner + set the\n       discount value; when unticked, hide it. Default state: UNCHECKED. */\n    var cb = document.getElementById('tmc-apply-credit');\n    if (cb) {\n      setApplied(false, creditDollars); /* default state */\n      cb.addEventListener('change', function () {\n        setApplied(cb.checked, creditDollars);\n      });\n    }\n  }\n  function load() {\n    try {\n      var raw = localStorage.getItem('tmc_session_token') || localStorage.getItem('tmc_token');\n      if (!raw) return;\n      fetch('/api/get-referral', { headers: { 'Authorization': 'Bearer ' + raw } })\n        .then(function (r) { return r.ok ? r.json() : null; })\n        .then(function (d) {\n          if (!d || !d.success) return;\n          var c = (typeof d.credit_available === 'number') ? d.credit_available : 0;\n          inject(c);\n        })\n        .catch(function () {});\n    } catch (e) {}\n  }\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', load);\n  } else { load(); }\n\n  /* Wrap fetch so any POST to /api/create-checkout automatically carries\n     apply_referral_credit based on the checkbox, AND any { free:true,\n     redirect } response is honored as a window.location.href redirect\n     (the existing handlers expect { url } from Stripe; they wouldn't\n     know what to do with free:true otherwise). */\n  var origFetch = window.fetch && window.fetch.bind(window);\n  if (!origFetch || window.__tmcCheckoutWrapped) return;\n  window.__tmcCheckoutWrapped = true;\n  window.fetch = function (input, init) {\n    try {\n      var url = (typeof input === 'string') ? input : (input && input.url) || '';\n      if (url && url.indexOf('/api/create-checkout') !== -1 && init && init.method === 'POST') {\n        var cb = document.getElementById('tmc-apply-credit');\n        var apply = cb ? !!cb.checked : true;\n        try {\n          var b = init.body ? JSON.parse(init.body) : {};\n          if (typeof b.apply_referral_credit === 'undefined') b.apply_referral_credit = apply;\n          init = Object.assign({}, init, { body: JSON.stringify(b) });\n        } catch (e) { /* if body isn't JSON, leave it alone */ }\n        return origFetch(input, init).then(function (resp) {\n          /* clone so existing handlers can still read it */\n          var cloned = resp.clone();\n          cloned.json().then(function (d) {\n            if (d && d.free === true && d.redirect) {\n              window.location.href = d.redirect;\n            }\n          }).catch(function () {});\n          return resp;\n        });\n      }\n    } catch (e) {}\n    return origFetch(input, init);\n  };\n})();\n</script>\n</head>\n<body class=\"wide-page\">\n<div class=\"nav\">\n  <div class=\"bk\" onclick=\"history.back()\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Pricing</span></div>\n<a href=\"/dashboard.html\" aria-label=\"TapMyCar\" style=\"display:flex;align-items:center;text-decoration:none\"><img src=\"/logo.png\" alt=\"TapMyCar\" class=\"nav-logo-img\" style=\"height:36px;width:auto\"></a></div>\n<div class=\"chev\"></div>\n<div class=\"page\"><div class=\"page-inner\">\n\n  <div style=\"text-align:center;padding:8px 0 20px\">\n    <div style=\"font-size:22px;font-weight:800;color:var(--bk)\">Simple pricing</div>\n    <div style=\"font-size:13px;color:var(--gy);margin-top:4px\">Free to try. Upgrade when you're ready.</div>\n  </div>\n\n  <!-- Referral banners -->\n  <div id=\"discount-banner\" style=\"display:none;background:#DCFCE7;border:1.5px solid #BBF7D0;border-radius:14px;padding:12px 16px;margin-bottom:12px\">\n    <div style=\"font-size:13px;font-weight:700;color:#166534\">Referral discount applied!</div>\n    <div style=\"font-size:11px;color:#15803D;margin-top:2px\">Your referral credits have been applied below.</div>\n  </div>\n  <div id=\"reward-banner\" style=\"display:none;background:#FFF3EC;border:1.5px solid #FFE4CC;border-radius:14px;padding:12px 16px;margin-bottom:12px\">\n    <div style=\"font-size:13px;font-weight:700;color:#FF6B00\">You have a pending reward!</div>\n    <div style=\"font-size:11px;color:#92400E;margin-top:2px\">Go to Settings → Referrals to claim your Free Standard plan or $4.99 coupon.</div>\n  </div>\n\n  <!-- STANDARD - HERO -->\n  <div class=\"plan-card hero\">\n    <div class=\"hero-badge\">Most Popular</div>\n    <div class=\"plan-top\">\n      <div class=\"plan-name\">Standard</div>\n      <div id=\"std-price\" class=\"plan-price\">$9.99 <span class=\"plan-sub\">today, then $9.99/yr</span></div>\n    </div>\n    <div class=\"plan-tagline\">Physical NFC + QR sticker for your car. 30-day free trial before annual plan begins.</div>\n    <div class=\"bullets\"><!-- TMC_PRICING_REFRESH -->\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>Weatherproof NFC + QR sticker ships to your door</div>\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>Unlimited masked calls · your number never shared</div>\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>Email + push alerts on every scan</div>\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>Emergency contact auto-forward after 3 missed calls</div>\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>Full scan history with location map</div>\n    </div>\n    <div class=\"prepay-row\" id=\"std-prepay\" onclick=\"togglePrepay('std')\">\n      <div class=\"prepay-check\"></div>\n      <div class=\"prepay-label\">Also prepay <b>year 1</b> now (+$9.99) · skip the day-30 charge</div>\n    </div>\n    <button class=\"btn\" id=\"std-btn\" onclick=\"checkout('direct', 'standard')\">Get Standard — <span id=\"std-btn-amt\">$9.99</span></button>\n    <div class=\"btn-err\" id=\"std-err\"></div>\n    <div class=\"disclosure\">\n      <span id=\"std-disclose\">Your card is charged $9.99 today for your Standard sticker, which ships in 2–3 business days. On day 30, your $9.99/year annual plan begins and renews yearly until you cancel. Cancel anytime in Settings.</span><br>\n      By continuing you agree to our <a href=\"/terms.html\">Terms</a> and <a href=\"/privacy.html\">Privacy Policy</a>.\n    </div>\n  </div>\n\n  <!-- PREMIUM -->\n  <div class=\"plan-card\">\n    <div class=\"plan-top\">\n      <div class=\"plan-name\">Premium</div>\n      <div id=\"prem-price\" class=\"plan-price\">$24.99 <span class=\"plan-sub\">today, then $19.99/yr</span></div>\n    </div>\n    <div class=\"plan-tagline\">3 stickers for your whole household  same TapMyCar privacy across every car you drive.</div>\n    <div class=\"bullets\">\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>Everything in Standard</div>\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>3 stickers (one for each family vehicle)</div>\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>3 gift codes to share with family</div>\n      <div class=\"bullet\"><div class=\"bullet-dot\"></div>Priority support</div>\n    </div>\n    <div class=\"prepay-row\" id=\"prem-prepay\" onclick=\"togglePrepay('prem')\">\n      <div class=\"prepay-check\"></div>\n      <div class=\"prepay-label\">Also prepay <b>year 1</b> now (+$19.99) · skip the day-30 charge</div>\n    </div>\n    <button class=\"btn-o\" id=\"prem-btn\" onclick=\"checkout('direct', 'premium')\">Get Premium — <span id=\"prem-btn-amt\">$24.99</span></button>\n    <div class=\"btn-err\" id=\"prem-err\"></div>\n    <div class=\"disclosure\">\n      <span id=\"prem-disclose\">Your card is charged $24.99 today for your 3 Premium stickers, which ship in 2–3 business days. On day 30, your $19.99/year annual plan begins and renews yearly until you cancel. Cancel anytime in Settings.</span>\n    </div>\n  </div>\n\n  <!-- FREE ETAG - LEAD MAGNET -->\n  <div class=\"plan-card ghost\">\n    <div class=\"plan-top\">\n      <div class=\"plan-name ghost\">Free eTag</div>\n      <div style=\"background:#E5E7EB;color:#6B7280;font-size:11px;font-weight:700;padding:3px 13px;border-radius:99px\">Free</div>\n    </div>\n    <!-- TMC_PATCH64 -->\n    <div class=\"plan-tagline\" style=\"color:#9CA3AF\">Get your digital QR code free. When you’re ready to switch it on, just $1 lets you experience everything for 30 days — no sticker needed yet.</div>\n    <div class=\"bullets\">\n      <div class=\"bullet mute\"><div class=\"bullet-dot\"></div>Printable QR code — free to download, put it on your car today</div>\n      <div class=\"bullet mute\"><div class=\"bullet-dot\"></div>$1 activation lets you try the full service for 30 days</div>\n      <div class=\"bullet mute\"><div class=\"bullet-dot\"></div>Pick Standard or Premium when you activate</div>\n    </div>\n    <button class=\"btn-g\" onclick=\"checkout('etag_free', null)\">Get my free eTag</button>\n    <div class=\"disclosure\">Free to download. Your tag is inactive until you activate it for $1. Activation lets you experience TapMyCar for 30 days; on day 30 your chosen plan’s sticker ships and is charged ($9.99 Standard / $24.99 Premium), and on day 60 your annual plan begins ($9.99/yr Standard / $19.99/yr Premium), renewing yearly until you cancel. You can cancel anytime before a charge in Settings. Full details: <a href=\"/pricing.html\" style=\"color:#FF6B00\">tapmycar.io/pricing</a>.</div>\n  </div>\n\n  <!-- BUSINESS -->\n  <div class=\"plan-card\">\n    <div class=\"plan-top\">\n      <div class=\"plan-name\">Business / Fleet</div>\n      <div class=\"plan-price\">$49 <span class=\"plan-sub\">/month</span></div>\n    </div>\n    <div class=\"plan-tagline\">Bulk stickers with your logo, fleet dashboard, dedicated support.</div>\n    <button class=\"btn-o\" onclick=\"window.location.href='/business.html'\">Contact us</button>\n  </div>\n\n  <div style=\"padding:16px 0 8px;text-align:center;font-size:11px;color:#9CA3AF;line-height:1.6\">\n    <!-- TMC_PATCH31_REFUND: clearer refund copy -->\n    <!-- TMC_PATCH34_AUTOMATIC_TAX: tax disclaimer -->\n    Not satisfied? Request a refund within 14 days — a $1 service fee is retained. After 14 days, the plan is non-refundable.<br>\n    Prices shown do not include sales tax. Tax is calculated at checkout based on your shipping address.<br>\n    Annual subscription is refundable within 14 days of each annual charge ($1 service fee retained).<br>\n    Activation fees, sticker fees, and prepaid bundle extras are non-refundable.<br>\n    <a href=\"/terms.html\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Full Terms</a> · <a href=\"/privacy.html\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Privacy Policy</a>\n  </div>\n\n</div></div>\n\n<div class=\"toast\" id=\"toast\"><div class=\"toast-ic\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><span id=\"toast-msg\"></span></div>\n\n<script src=\"/app.js\"></script>\n<script>\n// ─── PREPAY TOGGLE ──────────────────────────────────────────\nconst prepayState = { std: false, prem: false };\n\nfunction togglePrepay(which) {\n  prepayState[which] = !prepayState[which];\n  const row = document.getElementById(which + '-prepay');\n  row.classList.toggle('on', prepayState[which]);\n  updateButtonLabels();\n}\n\nfunction updateButtonLabels() {\n  // Standard\n  const stdAmt = prepayState.std ? '$19.98 today' : '$9.99';\n  document.getElementById('std-btn-amt').textContent = stdAmt;\n  /* TMC_PATCH64 */ document.getElementById('std-disclose').textContent = prepayState.std\n    ? 'Your card is charged $19.98 today ($9.99 sticker + $9.99 year 1). Your sticker ships in 2-3 business days, and your next $9.99/year charge is on the 365-day anniversary, renewing yearly until you cancel.'\n    : 'Your card is charged $9.99 today for your Standard sticker, which ships in 2-3 business days. On day 30, your $9.99/year annual plan begins and renews yearly until you cancel. Cancel anytime in Settings.';\n  // Premium\n  const premAmt = prepayState.prem ? '$44.98 today' : '$24.99';\n  document.getElementById('prem-btn-amt').textContent = premAmt;\n  /* TMC_PATCH64 */ document.getElementById('prem-disclose').textContent = prepayState.prem\n    ? 'Your card is charged $44.98 today ($24.99 for 3 stickers + $19.99 year 1). Your stickers ship in 2-3 business days, and your next $19.99/year charge is on the 365-day anniversary, renewing yearly until you cancel.'\n    : 'Your card is charged $24.99 today for your 3 Premium stickers, which ship in 2-3 business days. On day 30, your $19.99/year annual plan begins and renews yearly until you cancel. Cancel anytime in Settings.';\n}\n\n// ─── CHECKOUT ──────────────────────────────────────────────\nasync function checkout(flow, plan) {\n  // Must be signed in — bounce to register if not\n  const session = getSession();\n  if (!session || !session.token) {\n    // Remember plan choice + forward to register\n    if (flow === 'etag_free') {\n      window.location.href = '/register.html';\n    } else {\n      window.location.href = '/register.html?plan=' + plan + '&flow=' + flow + (prepayState[plan === 'standard' ? 'std' : 'prem'] ? '&prepay=1' : '');\n    }\n    return;\n  }\n\n  const btnId = plan === 'standard' ? 'std-btn' : plan === 'premium' ? 'prem-btn' : null;\n  const errId = plan === 'standard' ? 'std-err' : plan === 'premium' ? 'prem-err' : null;\n  const btn = btnId ? document.getElementById(btnId) : null;\n  const err = errId ? document.getElementById(errId) : null;\n\n  if (btn) { btn.disabled = true; btn.textContent = 'Loading...'; }\n  if (err) { err.classList.remove('show'); err.textContent = ''; }\n\n  const prepay = (plan === 'standard') ? prepayState.std : (plan === 'premium') ? prepayState.prem : false;\n  const body = {\n    user_id: session.token,\n    flow,\n    plan,\n    prepay,\n    referral_discount: window.__refDiscount || 0\n  };\n\n  try {\n    const res = await fetch('/api/create-checkout', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(body)\n    });\n    const data = await res.json();\n\n    if (data.free && data.redirect) {\n      // Free eTag — no Stripe, just redirect\n      window.location.href = data.redirect;\n      return;\n    }\n\n    if (data.url) {\n      // Stripe checkout — redirect to Stripe\n      window.location.href = data.url;\n      return;\n    }\n\n    if (data.error) {\n      if (err) { err.textContent = data.error; err.classList.add('show'); }\n      else { showToast(data.error); }\n    }\n  } catch (e) {\n    if (err) { err.textContent = 'Network error — try again'; err.classList.add('show'); }\n    else { showToast('Network error'); }\n  } finally {\n    if (btn) {\n      btn.disabled = false;\n      // Restore label\n      if (plan === 'standard') btn.innerHTML = 'Get Standard — <span id=\"std-btn-amt\">' + (prepayState.std ? '$19.98 today' : '$9.99') + '</span>';\n      else if (plan === 'premium') btn.innerHTML = 'Get Premium — <span id=\"prem-btn-amt\">' + (prepayState.prem ? '$44.98 today' : '$24.99') + '</span>';\n    }\n  }\n}\n\n// ─── REFERRAL DISCOUNT (existing logic preserved) ──────────\nasync function loadReferralDiscount() {\n  const s = getSession();\n  if (!s || !s.token) return;\n  try {\n    const res = await fetch('/api/get-referral?user_id=' + s.token);\n    const data = await res.json();\n    if (!data.success) return;\n    if (data.referral_reward_pending === 'choice') {\n      document.getElementById('reward-banner').style.display = 'block';\n    }\n    /* TMC_PATCH45B_FIX2: this block used to unconditionally show the\n       discount-banner and set window.__refDiscount on every page load,\n       racing with Patch 45b-fix's checkbox handler. The checkbox now\n       owns both bits of state, so this block is intentionally disabled. */\n    /* if (data.referral_credits >= 3) {\n         window.__refDiscount = parseFloat(data.referral_credits);\n         document.getElementById('discount-banner').style.display = 'block';\n       } */\n  } catch(e) { console.error(e); }\n}\nloadReferralDiscount();\nupdateButtonLabels();\n</script>\n<script>if ('serviceWorker' in navigator) { navigator.serviceWorker.register('/sw.js'); }</script>\n<script src=\"/tmc-redesign.js\"></script>\n</body>\n</html>\n", "public/landing.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <link rel=\"manifest\" href=\"/manifest.json\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"TapMyCar\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0\">\n<title>TapMyCar — Privacy-first vehicle contact | Praman Tech LLC</title>\n<link rel=\"stylesheet\" href=\"/app.css\">\n<link rel=\"stylesheet\" href=\"/tmc-redesign.css\">\n<style>\n* { box-sizing: border-box; margin: 0; padding: 0; }\nbody { font-family: 'Inter', sans-serif; background: #fff; color: #111; max-width: 430px; margin: 0 auto; }\n\n/* HERO */\n.hero { background: #FF6B00; padding: 48px 24px 40px; text-align: center; position: relative; overflow: hidden; }\n.hero-ring1 { position: absolute; width: 200px; height: 200px; border-radius: 50%; background: rgba(255,255,255,.06); right: -60px; top: -60px; }\n.hero-ring2 { position: absolute; width: 140px; height: 140px; border-radius: 50%; background: rgba(255,255,255,.04); left: -40px; bottom: -40px; }\n.hero-badge { display: inline-flex; align-items: center; gap: 6px; background: rgba(255,255,255,.2); border-radius: 99px; padding: 5px 14px; font-size: 11px; font-weight: 600; color: #fff; margin-bottom: 20px; }\n.hero-badge-dot { width: 6px; height: 6px; border-radius: 50%; background: #fff; animation: pulse 1.6s ease-in-out infinite; }\n.hero h1 { font-size: 34px; font-weight: 800; color: #fff; letter-spacing: -.6px; line-height: 1.1; margin-bottom: 12px; }\n.hero h1 span { color: rgba(255,255,255,.7); }\n.hero p { font-size: 14px; color: rgba(255,255,255,.75); line-height: 1.6; margin-bottom: 28px; max-width: 300px; margin-left: auto; margin-right: auto; }\n.hero-btns { display: flex; flex-direction: column; gap: 10px; }\n.hero-btn-primary { background: #fff; color: #FF6B00; font-size: 15px; font-weight: 800; padding: 15px 0; border-radius: 14px; text-decoration: none; display: block; box-shadow: 0 8px 24px rgba(0,0,0,.15); }\n.hero-btn-secondary { background: rgba(255,255,255,.15); color: #fff; font-size: 14px; font-weight: 600; padding: 13px 0; border-radius: 14px; text-decoration: none; display: block; border: 1.5px solid rgba(255,255,255,.3); }\n\n/* SECTIONS */\n.section { padding: 36px 24px; }\n.section-label { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: #FF6B00; margin-bottom: 8px; }\n.section h2 { font-size: 24px; font-weight: 800; color: #111; margin-bottom: 6px; line-height: 1.2; }\n.section p { font-size: 13px; color: #6B7280; line-height: 1.6; margin-bottom: 24px; }\n\n/* RISK CARDS */\n.risk-grid { display: flex; flex-direction: column; gap: 10px; }\n.risk { display: flex; gap: 12px; align-items: flex-start; background: #FEF2F2; border-radius: 12px; padding: 14px; border: .5px solid #FECACA; }\n.risk-icon { width: 32px; height: 32px; border-radius: 8px; background: #FEE2E2; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }\n.risk-icon svg { width: 16px; height: 16px; stroke: #DC2626; fill: none; stroke-width: 2; stroke-linecap: round; }\n.risk h3 { font-size: 13px; font-weight: 700; color: #991B1B; margin-bottom: 2px; }\n.risk p { font-size: 11px; color: #B91C1C; line-height: 1.5; margin-bottom: 0; }\n\n/* SOLUTION CARDS */\n.sol-grid { display: flex; flex-direction: column; gap: 10px; }\n.sol { display: flex; gap: 12px; align-items: flex-start; background: #F0FDF4; border-radius: 12px; padding: 14px; border: .5px solid #BBF7D0; }\n.sol-icon { width: 32px; height: 32px; border-radius: 8px; background: #DCFCE7; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }\n.sol-icon svg { width: 16px; height: 16px; stroke: #16A34A; fill: none; stroke-width: 2; stroke-linecap: round; }\n.sol h3 { font-size: 13px; font-weight: 700; color: #166534; margin-bottom: 2px; }\n.sol p { font-size: 11px; color: #15803D; line-height: 1.5; margin-bottom: 0; }\n\n/* TMC_STICKER_FLASH_FIX: hide hero sticker on first paint until JS decides */\n#tmc-hero-sticker.tmc-pre-hidden { visibility: hidden; }\n\n/* TMC_BRANDING: hero sticker scene + stats card + marquee + step ring */\n.tmc-scene { position: relative; width: 220px; height: 220px; margin: 6px auto 22px; perspective: 1000px; z-index: 2; }\n.tmc-scene-glow { position: absolute; inset: -20px; border-radius: 50%; background: radial-gradient(circle, rgba(255,255,255,.40) 0%, transparent 60%); filter: blur(28px); animation: tmcSceneGlow 3.2s ease-in-out infinite alternate; }\n@keyframes tmcSceneGlow { from { opacity: .5; transform: scale(.92); } to { opacity: 1; transform: scale(1.1); } }\n.tmc-scene-ring { position: absolute; inset: -10px; border-radius: 50%; border: 2px solid rgba(255,255,255,.28); animation: tmcRingSpin 20s linear infinite; }\n.tmc-scene-ring::before { content: ''; position: absolute; width: 14px; height: 14px; border-radius: 50%; background: #fff; top: -7px; left: 50%; margin-left: -7px; box-shadow: 0 0 20px #fff, 0 0 40px rgba(255,255,255,.6); }\n.tmc-scene-ring2 { position: absolute; inset: 6px; border-radius: 50%; border: 1px dashed rgba(255,255,255,.4); animation: tmcRingSpin 30s linear infinite reverse; }\n@keyframes tmcRingSpin { to { transform: rotate(360deg); } }\n.tmc-sticker-3d { position: absolute; inset: 34px; border-radius: 30px; background: linear-gradient(135deg,#fff 0%,#f0f0f0 100%); box-shadow: 0 0 0 4px #FF6B00, 0 22px 50px rgba(0,0,0,.35), 0 12px 28px rgba(255,107,0,.5), inset 0 2px 0 rgba(255,255,255,.85); display: flex; flex-direction: column; align-items: center; justify-content: center; overflow: hidden; transform-style: preserve-3d; animation: tmcStickerFloat 6s ease-in-out infinite; padding: 10px; }\n@keyframes tmcStickerFloat { 0%,100% { transform: rotateY(-32deg) rotateX(14deg) translateY(0); } 50% { transform: rotateY(32deg) rotateX(-10deg) translateY(-10px); } }\n.tmc-scene:hover .tmc-sticker-3d { animation-play-state: paused; }\n.tmc-scene { cursor: pointer; }\n.tmc-scene:hover .tmc-scene-glow { animation: none; opacity: 1; transform: scale(1.2); }\n.tmc-scene:hover .tmc-scene-ring { animation-duration: 6s; }\n.tmc-scene:hover .tmc-scene-ring2 { animation-duration: 9s; }\n.tmc-sticker-3d img { width: 100%; height: 100%; object-fit: contain; display: block; }\n.tmc-sticker-3d-fallback { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; }\n.tmc-sticker-3d-fallback svg { width: 60px; height: 60px; }\n.tmc-sticker-3d-fallback .l1 { font-size: 12px; font-weight: 900; color: #111; letter-spacing: 1.5px; }\n.tmc-sticker-3d-fallback .l2 { font-size: 8px; color: #FF6B00; font-weight: 700; letter-spacing: 2px; }\n\n.tmc-stats { display: grid; grid-template-columns: repeat(3, 1fr); padding: 22px 22px; background: #fff; position: relative; margin-top: -22px; z-index: 4; border-top-left-radius: 24px; border-top-right-radius: 24px; box-shadow: 0 -8px 24px rgba(0,0,0,.06); }\n.tmc-stat { text-align: center; position: relative; }\n.tmc-stat:not(:last-child)::after { content: ''; position: absolute; right: 0; top: 14%; bottom: 14%; width: 1px; background: #F0F0F0; }\n.tmc-stat-n { font-size: 20px; font-weight: 900; color: #FF6B00; letter-spacing: -.5px; line-height: 1.1; }\n.tmc-stat-l { font-size: 9px; color: #6B7280; text-transform: uppercase; letter-spacing: .8px; font-weight: 600; margin-top: 4px; }\n\n.tmc-trust { background: #FFF7ED; border-top: 1px solid #FED7AA; border-bottom: 1px solid #FED7AA; overflow: hidden; padding: 11px 0; position: relative; }\n.tmc-trust::before, .tmc-trust::after { content: ''; position: absolute; top: 0; bottom: 0; width: 40px; z-index: 2; pointer-events: none; }\n.tmc-trust::before { left: 0; background: linear-gradient(90deg, #FFF7ED, transparent); }\n.tmc-trust::after { right: 0; background: linear-gradient(-90deg, #FFF7ED, transparent); }\n.tmc-trust-track { display: flex; gap: 28px; animation: tmcMarquee 22s linear infinite; white-space: nowrap; width: max-content; }\n@keyframes tmcMarquee { to { transform: translateX(-50%); } }\n.tmc-trust-item { display: inline-flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 700; color: #9A3412; }\n.tmc-trust-item svg { width: 13px; height: 13px; }\n\n/* Pulsing ring around How it works step numbers */\n.step .step-num { position: relative; }\n.step .step-num::after { content: ''; position: absolute; inset: -4px; border-radius: 14px; background: linear-gradient(135deg, #FF6B00, #FF9540); opacity: .25; z-index: -1; animation: tmcRingPulse 2s ease-in-out infinite; }\n@keyframes tmcRingPulse { 0%,100% { transform: scale(1); opacity: .25; } 50% { transform: scale(1.35); opacity: 0; } }\n\n/* TMC_BREATHE: continuous slow breathing on every risk/sol/feat card */\n.risk, .sol, .feat { will-change: transform, box-shadow; transform: translateY(0); }\n\n.risk { box-shadow: 0 2px 6px rgba(220,38,38,.06); animation: tmcBreatheRed 10s ease-in-out infinite; }\n.risk:nth-child(2) { animation-delay: -2.5s; }\n.risk:nth-child(3) { animation-delay: -5s; }\n.risk:nth-child(4) { animation-delay: -7.5s; }\n.risk-icon { animation: tmcBreatheIconRed 10s ease-in-out infinite; will-change: transform; }\n.risk:nth-child(2) .risk-icon { animation-delay: -2.5s; }\n.risk:nth-child(3) .risk-icon { animation-delay: -5s; }\n.risk:nth-child(4) .risk-icon { animation-delay: -7.5s; }\n@keyframes tmcBreatheRed {\n  0%, 100% { transform: translateY(0); box-shadow: 0 2px 6px rgba(220,38,38,.06); }\n  50%      { transform: translateY(-4px); box-shadow: 0 18px 36px rgba(220,38,38,.22), 0 4px 10px rgba(220,38,38,.08); }\n}\n@keyframes tmcBreatheIconRed { 0%,100% { transform: scale(1) rotate(0); } 50% { transform: scale(1.08) rotate(-4deg); } }\n\n.sol { box-shadow: 0 2px 6px rgba(22,163,74,.06); animation: tmcBreatheGreen 11s ease-in-out infinite; }\n.sol:nth-child(2) { animation-delay: -2.75s; }\n.sol:nth-child(3) { animation-delay: -5.5s; }\n.sol:nth-child(4) { animation-delay: -8.25s; }\n.sol-icon { animation: tmcBreatheIconGreen 11s ease-in-out infinite; will-change: transform; }\n.sol:nth-child(2) .sol-icon { animation-delay: -2.75s; }\n.sol:nth-child(3) .sol-icon { animation-delay: -5.5s; }\n.sol:nth-child(4) .sol-icon { animation-delay: -8.25s; }\n@keyframes tmcBreatheGreen {\n  0%, 100% { transform: translateY(0); box-shadow: 0 2px 6px rgba(22,163,74,.06); }\n  50%      { transform: translateY(-4px); box-shadow: 0 18px 36px rgba(22,163,74,.22), 0 4px 10px rgba(22,163,74,.08); }\n}\n@keyframes tmcBreatheIconGreen { 0%,100% { transform: scale(1) rotate(0); } 50% { transform: scale(1.08) rotate(4deg); } }\n\n.feat { box-shadow: 0 2px 6px rgba(255,107,0,.05); animation: tmcBreatheOrange 12s ease-in-out infinite; }\n.feat:nth-child(2) { animation-delay: -2s; }\n.feat:nth-child(3) { animation-delay: -4s; }\n.feat:nth-child(4) { animation-delay: -6s; }\n.feat:nth-child(5) { animation-delay: -8s; }\n.feat:nth-child(6) { animation-delay: -10s; }\n.feat-icon { animation: tmcBreatheIconOrange 12s ease-in-out infinite; will-change: transform, background; }\n.feat:nth-child(2) .feat-icon { animation-delay: -2s; }\n.feat:nth-child(3) .feat-icon { animation-delay: -4s; }\n.feat:nth-child(4) .feat-icon { animation-delay: -6s; }\n.feat:nth-child(5) .feat-icon { animation-delay: -8s; }\n.feat:nth-child(6) .feat-icon { animation-delay: -10s; }\n@keyframes tmcBreatheOrange {\n  0%, 100% { transform: translateY(0); box-shadow: 0 2px 6px rgba(255,107,0,.05); border-color: #E5E7EB; }\n  50%      { transform: translateY(-4px); box-shadow: 0 18px 36px rgba(255,107,0,.22), 0 4px 10px rgba(255,107,0,.08); border-color: #FED7AA; }\n}\n@keyframes tmcBreatheIconOrange { 0%,100% { transform: scale(1) rotate(0); background: #FFF3EC; } 50% { transform: scale(1.1) rotate(-5deg); background: #FED7AA; } }\n\n/* Respect reduced-motion preference */\n@media (prefers-reduced-motion: reduce) {\n  .risk, .sol, .feat, .risk-icon, .sol-icon, .feat-icon { animation: none !important; }\n}\n\n/* HOW IT WORKS */\n.steps { display: flex; flex-direction: column; gap: 16px; }\n.step { display: flex; gap: 14px; align-items: flex-start; }\n.step-num { width: 36px; height: 36px; border-radius: 10px; background: #FF6B00; display: flex; align-items: center; justify-content: center; font-size: 15px; font-weight: 800; color: #fff; flex-shrink: 0; }\n.step-body h3 { font-size: 14px; font-weight: 700; color: #111; margin-bottom: 3px; }\n.step-body p { font-size: 12px; color: #6B7280; line-height: 1.5; margin-bottom: 0; }\n\n/* FEATURES */\n.features-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 8px; }\n.feat { background: #F9FAFB; border-radius: 14px; padding: 16px; border: .5px solid #E5E7EB; }\n.feat-icon { width: 36px; height: 36px; border-radius: 10px; background: #FFF3EC; display: flex; align-items: center; justify-content: center; margin-bottom: 10px; }\n.feat-icon svg { width: 18px; height: 18px; stroke: #FF6B00; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.feat h3 { font-size: 13px; font-weight: 700; color: #111; margin-bottom: 4px; }\n.feat p { font-size: 11px; color: #6B7280; line-height: 1.5; margin-bottom: 0; }\n\n/* PRICING */\n.pricing-card { border: 2px solid #FF6B00; border-radius: 18px; padding: 20px; margin-bottom: 12px; }\n.pricing-card h3 { font-size: 18px; font-weight: 800; color: #111; margin-bottom: 4px; }\n.pricing-price { font-size: 32px; font-weight: 800; color: #FF6B00; margin-bottom: 4px; }\n.pricing-price span { font-size: 14px; color: #6B7280; font-weight: 400; }\n.pricing-desc { font-size: 12px; color: #6B7280; margin-bottom: 16px; }\n.pricing-features { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; }\n.pf { display: flex; align-items: center; gap: 8px; font-size: 12px; color: #111; }\n.pf-dot { width: 6px; height: 6px; border-radius: 1px; background: #FF6B00; flex-shrink: 0; }\n\n/* LEARN MORE BUTTON */\n.learn-btn { display: flex; align-items: center; justify-content: center; gap: 6px; background: #FFF3EC; color: #FF6B00; font-size: 13px; font-weight: 700; padding: 12px 0; border-radius: 12px; text-decoration: none; border: 1.5px solid #FFE4CC; margin-top: 16px; }\n\n/* APP DOWNLOAD BANNER */\n.app-banner { background: #111; padding: 24px; text-align: center; }\n.app-banner h3 { font-size: 18px; font-weight: 800; color: #fff; margin-bottom: 6px; }\n.app-banner p { font-size: 12px; color: #9CA3AF; margin-bottom: 16px; line-height: 1.5; }\n.app-btn { background: #FF6B00; color: #fff; font-size: 14px; font-weight: 700; padding: 14px 0; border-radius: 13px; text-decoration: none; display: block; margin-bottom: 8px; }\n.app-sub { font-size: 10px; color: #6B7280; }\n\n/* TESTIMONIAL */\n.testimonial { background: #F9FAFB; border-radius: 16px; padding: 20px; border: .5px solid #E5E7EB; margin-top: 8px; }\n.testimonial p { font-size: 14px; color: #111; line-height: 1.6; font-style: italic; margin-bottom: 12px; }\n.test-author { display: flex; align-items: center; gap: 10px; }\n.test-av { width: 36px; height: 36px; border-radius: 50%; background: #FF6B00; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; color: #fff; }\n.test-name { font-size: 13px; font-weight: 700; color: #111; }\n.test-sub { font-size: 11px; color: #6B7280; }\n\n/* CTA */\n.cta { background: #FF6B00; padding: 36px 24px; text-align: center; }\n.cta h2 { font-size: 24px; font-weight: 800; color: #fff; margin-bottom: 8px; }\n.cta p { font-size: 13px; color: rgba(255,255,255,.8); margin-bottom: 24px; line-height: 1.6; }\n.cta-btn { background: #fff; color: #FF6B00; font-size: 15px; font-weight: 800; padding: 15px 0; border-radius: 14px; text-decoration: none; display: block; }\n\n/* FOOTER */\n.footer { padding: 20px 24px; border-top: .5px solid #E5E7EB; text-align: center; }\n.footer p { font-size: 11px; color: #9CA3AF; }\n.footer a { color: #FF6B00; text-decoration: none; font-weight: 600; }\n\n@keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.45;transform:scale(.75)} }\n\n/* TMC_V3BOLD: mobile-friendly always-on animations + tap effects */\n@keyframes tmcCardFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }\n@keyframes tmcIconBreath { 0%,100% { transform: scale(1) rotate(0deg); } 50% { transform: scale(1.06) rotate(-2deg); } }\n@keyframes tmcSweep { 0% { left: -120%; } 60%, 100% { left: 150%; } }\n@keyframes tmcDoubleRing { 0%,100% { transform: scale(1); opacity: .3; } 50% { transform: scale(1.4); opacity: 0; } }\n\n/* HERO buttons  3D press + shimmer  always works on mobile */\n.hero-btn-primary {\n  background: linear-gradient(135deg, #fff 0%, #fff5ee 100%) !important;\n  box-shadow: 0 6px 0 rgba(196,84,10,.55), 0 14px 30px rgba(0,0,0,.22) !important;\n  position: relative; overflow: hidden;\n  transition: transform .18s cubic-bezier(.2,.8,.2,1), box-shadow .18s ease;\n}\n.hero-btn-primary::before {\n  content: ''; position: absolute; top: 0; left: -120%; width: 70%; height: 100%;\n  background: linear-gradient(110deg, transparent 30%, rgba(255,107,0,.4) 50%, transparent 70%);\n  animation: tmcSweep 2.6s ease-in-out infinite;\n  pointer-events: none;\n}\n.hero-btn-primary:active { transform: translateY(3px); box-shadow: 0 0 0 rgba(196,84,10,.55), 0 6px 14px rgba(0,0,0,.18) !important; }\n.hero-btn-secondary {\n  transition: background .25s ease, border-color .25s ease, transform .18s ease;\n  position: relative; overflow: hidden;\n}\n.hero-btn-secondary:active { background: rgba(255,255,255,.35); transform: translateY(2px); }\n\n/* NAV button (Get Started) */\n.tmc-nav-cta { transition: transform .2s ease, box-shadow .2s ease !important; box-shadow: 0 6px 16px rgba(255,107,0,.4) !important; }\n.tmc-nav-cta:active { transform: translateY(2px); box-shadow: 0 2px 8px rgba(255,107,0,.45) !important; }\n\n/* RISK cards  float + tap press */\n.risk {\n  animation: tmcCardFloat 4s ease-in-out infinite;\n  transition: transform .15s ease, box-shadow .15s ease !important;\n  cursor: pointer;\n  box-shadow: 0 6px 16px rgba(220,38,38,.08);\n}\n.risk:nth-child(1) { animation-delay: 0s; }\n.risk:nth-child(2) { animation-delay: -1s; }\n.risk:nth-child(3) { animation-delay: -2s; }\n.risk:nth-child(4) { animation-delay: -3s; }\n.risk:active { transform: scale(.97) !important; box-shadow: 0 4px 8px rgba(220,38,38,.18) !important; }\n.risk-icon { animation: tmcIconBreath 4s ease-in-out infinite; }\n.risk:nth-child(2) .risk-icon { animation-delay: -1s; }\n.risk:nth-child(3) .risk-icon { animation-delay: -2s; }\n.risk:nth-child(4) .risk-icon { animation-delay: -3s; }\n\n/* SOLUTION cards */\n.sol {\n  animation: tmcCardFloat 4.5s ease-in-out infinite;\n  transition: transform .15s ease, box-shadow .15s ease !important;\n  cursor: pointer;\n  box-shadow: 0 6px 16px rgba(22,163,74,.08);\n}\n.sol:nth-child(1) { animation-delay: -.5s; }\n.sol:nth-child(2) { animation-delay: -1.5s; }\n.sol:nth-child(3) { animation-delay: -2.5s; }\n.sol:nth-child(4) { animation-delay: -3.5s; }\n.sol:active { transform: scale(.97) !important; box-shadow: 0 4px 8px rgba(22,163,74,.18) !important; }\n.sol-icon { animation: tmcIconBreath 4.5s ease-in-out infinite; }\n.sol:nth-child(2) .sol-icon { animation-delay: -1.5s; }\n.sol:nth-child(3) .sol-icon { animation-delay: -2.5s; }\n.sol:nth-child(4) .sol-icon { animation-delay: -3.5s; }\n\n/* STEP NUMBERS  double pulsing ring */\n.step .step-num {\n  position: relative;\n  background: linear-gradient(135deg, #FF6B00, #FF9540) !important;\n  box-shadow: 0 8px 20px rgba(255,107,0,.5), inset 0 2px 0 rgba(255,255,255,.35) !important;\n}\n.step .step-num::before {\n  content: ''; position: absolute; inset: -5px; border-radius: 15px;\n  background: linear-gradient(135deg, #FF6B00, #FF9540);\n  opacity: .3; z-index: -1;\n  animation: tmcDoubleRing 2s ease-in-out infinite;\n}\n.step .step-num::after {\n  content: ''; position: absolute; inset: -10px; border-radius: 18px;\n  background: linear-gradient(135deg, #FF6B00, #FF9540);\n  opacity: .15; z-index: -2;\n  animation: tmcDoubleRing 2s ease-in-out infinite .5s;\n}\n\n/* eTag toggle */\n#etag-toggle { transition: transform .18s ease, box-shadow .18s ease, background .25s ease !important; cursor: pointer; }\n#etag-toggle:active { transform: scale(.98) !important; background: #FFF7ED !important; }\n\n/* LEARN button (How TapMyCar solves this) */\n.learn-btn { transition: transform .18s ease, box-shadow .18s ease, background .25s ease, gap .25s ease !important; position: relative; overflow: hidden; }\n.learn-btn:active { transform: translateY(2px); background: #FFE0CC !important; }\n\n/* FEATURES grid */\n.feat {\n  animation: tmcCardFloat 5s ease-in-out infinite;\n  transition: transform .15s ease, box-shadow .15s ease !important;\n  cursor: pointer;\n  box-shadow: 0 4px 12px rgba(0,0,0,.04);\n}\n.feat:nth-child(1) { animation-delay: 0s; }\n.feat:nth-child(2) { animation-delay: -1.25s; }\n.feat:nth-child(3) { animation-delay: -2.5s; }\n.feat:nth-child(4) { animation-delay: -3.75s; }\n.feat:nth-child(5) { animation-delay: -5s; }\n.feat:nth-child(6) { animation-delay: -6.25s; }\n.feat:active { transform: scale(.97) !important; box-shadow: 0 4px 8px rgba(255,107,0,.18) !important; }\n.feat-icon { animation: tmcIconBreath 5s ease-in-out infinite; }\n\n/* PRICING cards */\n.pricing-card {\n  transition: transform .2s ease, box-shadow .2s ease !important;\n  cursor: pointer;\n  position: relative; overflow: hidden;\n}\n.pricing-card:active { transform: scale(.98) !important; }\n\n/* PRICING button (Get Standard / Get Premium / Get free eTag) */\n.tmc-cta-orange {\n  background: linear-gradient(135deg, #FF6B00, #FF8420) !important;\n  box-shadow: 0 6px 0 rgba(196,84,10,.45), 0 12px 28px rgba(255,107,0,.4) !important;\n  position: relative; overflow: hidden;\n  transition: transform .18s ease, box-shadow .18s ease;\n}\n.tmc-cta-orange::before {\n  content: ''; position: absolute; top: 0; left: -120%; width: 70%; height: 100%;\n  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.35) 50%, transparent 70%);\n  animation: tmcSweep 3s ease-in-out infinite;\n  pointer-events: none;\n}\n.tmc-cta-orange:active { transform: translateY(3px); box-shadow: 0 0 0 rgba(196,84,10,.45), 0 6px 14px rgba(255,107,0,.3) !important; }\n\n/* APP BANNER button */\n.app-btn {\n  background: linear-gradient(135deg, #FF6B00, #FF8420) !important;\n  box-shadow: 0 6px 0 rgba(196,84,10,.5), 0 14px 30px rgba(255,107,0,.4) !important;\n  position: relative; overflow: hidden;\n  transition: transform .18s ease, box-shadow .18s ease;\n}\n.app-btn::before {\n  content: ''; position: absolute; top: 0; left: -120%; width: 70%; height: 100%;\n  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.35) 50%, transparent 70%);\n  animation: tmcSweep 3s ease-in-out infinite;\n  pointer-events: none;\n}\n.app-btn:active { transform: translateY(3px); box-shadow: 0 0 0 rgba(196,84,10,.5), 0 6px 14px rgba(255,107,0,.3) !important; }\n\n/* TESTIMONIAL card */\n.testimonial {\n  animation: tmcCardFloat 5s ease-in-out infinite;\n  transition: transform .15s ease, box-shadow .15s ease !important;\n  cursor: pointer;\n  position: relative; overflow: hidden;\n}\n.testimonial::before {\n  content: '\\201C'; position: absolute; top: -8px; right: 12px;\n  font-family: Georgia, serif; font-size: 80px; color: #FF6B00;\n  opacity: .15; pointer-events: none; line-height: 1;\n}\n.testimonial:active { transform: scale(.98) !important; }\n.testimonial > * { position: relative; z-index: 1; }\n.test-av { box-shadow: 0 4px 12px rgba(255,107,0,.4); }\n\n/* FINAL CTA button  bigger 3D press */\n.cta-btn {\n  background: linear-gradient(135deg, #fff 0%, #fff5ee 100%) !important;\n  box-shadow: 0 6px 0 rgba(196,84,10,.55), 0 16px 36px rgba(0,0,0,.28) !important;\n  position: relative; overflow: hidden;\n  transition: transform .18s ease, box-shadow .18s ease;\n}\n.cta-btn::before {\n  content: ''; position: absolute; top: 0; left: -120%; width: 70%; height: 100%;\n  background: linear-gradient(110deg, transparent 30%, rgba(255,107,0,.4) 50%, transparent 70%);\n  animation: tmcSweep 2.8s ease-in-out infinite;\n  pointer-events: none;\n}\n.cta-btn:active { transform: translateY(3px); box-shadow: 0 0 0 rgba(196,84,10,.55), 0 6px 16px rgba(0,0,0,.2) !important; }\n\n/* eTag activation step circles  pulsing rings */\n.etag-step-num {\n  position: relative;\n  background: linear-gradient(135deg, #FF6B00, #FF9540) !important;\n  box-shadow: 0 4px 10px rgba(255,107,0,.45) !important;\n}\n.etag-step-num::before {\n  content: ''; position: absolute; inset: -3px; border-radius: 50%;\n  background: linear-gradient(135deg, #FF6B00, #FF9540);\n  opacity: .3; z-index: -1;\n  animation: tmcDoubleRing 2.2s ease-in-out infinite;\n}\n</style>\n<!-- Favicon -->\n<link rel=\"icon\" type=\"image/x-icon\" href=\"/favicon.ico\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<!-- SEO -->\n<meta name=\"description\" content=\"Strangers can reach you about your parked car without ever seeing your real phone number. NFC + QR sticker, masked calls, instant alerts. Just TapMyCar.\">\n<meta name=\"author\" content=\"Praman Tech LLC\">\n<!-- Open Graph -->\n<meta property=\"og:title\" content=\"TapMyCar — Privacy-first vehicle contact | Praman Tech LLC\">\n<meta property=\"og:description\" content=\"Strangers can reach you about your parked car without ever seeing your real phone number. NFC + QR sticker, masked calls, instant alerts. Just TapMyCar.\">\n<meta property=\"og:image\" content=\"https://tapmycar.io/og-image.png\">\n<meta property=\"og:url\" content=\"https://tapmycar.io/landing.html\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"TapMyCar\">\n<!-- Twitter Card -->\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"TapMyCar — Privacy-first vehicle contact | Praman Tech LLC\">\n<meta name=\"twitter:description\" content=\"Strangers can reach you about your parked car without ever seeing your real phone number. NFC + QR sticker, masked calls, instant alerts. Just TapMyCar.\">\n<meta name=\"twitter:image\" content=\"https://tapmycar.io/og-image.png\">\n</head>\n<body class=\"wide-page\">\n\n<!-- NAV -->\n<div style=\"display:flex;align-items:center;justify-content:space-between;padding:14px 24px;border-bottom:.5px solid #E5E7EB;position:sticky;top:0;background:#fff;z-index:100\">\n  <a href=\"/landing.html\" aria-label=\"TapMyCar\" style=\"display:flex;align-items:center;gap:12px;text-decoration:none;font-size:30px;font-weight:900;color:#111;letter-spacing:-2.5px;line-height:1\"><img src=\"/logo.png\" alt=\"\" style=\"height:52px;width:auto;display:block\"><span style=\"white-space:nowrap;display:inline-block\">Tap<span style=\"color:#FF6B00\">My</span>Car</span></a>\n  <a href=\"/register.html\" data-tmc-cta=\"1\" style=\"background:#FF6B00;color:#fff;font-size:12px;font-weight:700;padding:8px 16px;border-radius:10px;text-decoration:none\" class=\"tmc-nav-cta\">Get started</a>\n</div>\n\n<!-- HERO -->\n<div class=\"hero\">\n  <div class=\"hero-ring1\"></div>\n  <div class=\"hero-ring2\"></div>\n  <div class=\"hero-badge\"><div class=\"hero-badge-dot\"></div>Privacy + Safety  No app needed to contact</div>\n  <h1>Privacy for you.<br><span>Safety</span> for your car.</h1>\n  <p>Your car is always protected. Your identity is never exposed. Anyone can reach you  without ever seeing your real number.</p>\n  <!-- TMC_BRANDING 3D sticker scene -->\n  <div class=\"tmc-scene\" id=\"tmc-hero-scene\">\n    <div class=\"tmc-scene-glow\"></div>\n    <div class=\"tmc-scene-ring\"></div>\n    <div class=\"tmc-scene-ring2\"></div>\n    <div class=\"tmc-sticker-3d tmc-pre-hidden\" id=\"tmc-hero-sticker\">\n      <div class=\"tmc-sticker-3d-fallback\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FF6B00\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"2\"/><path d=\"M16.24 7.76a6 6 0 0 1 0 8.49m-8.48-.01a6 6 0 0 1 0-8.49m11.31-2.82a10 10 0 0 1 0 14.14m-14.14 0a10 10 0 0 1 0-14.14\"/></svg>\n        <div class=\"l1\">TAPMYCAR</div>\n        <div class=\"l2\">SCAN OR TAP</div>\n      </div>\n    </div>\n  </div>\n  <div class=\"hero-btns\">\n    <a href=\"/register.html\" data-tmc-cta=\"1\" class=\"hero-btn-primary\">Explore TapMyCar</a>\n<a href=\"/why.html\" class=\"hero-btn-secondary\">Why do I need this?</a>  </div>\n</div>\n\n<!-- TMC_BRANDING stats card peeking up over hero -->\n<div class=\"tmc-stats\">\n  <div class=\"tmc-stat\"><div class=\"tmc-stat-n\">Very</div><div class=\"tmc-stat-l\">Private</div></div>\n  <div class=\"tmc-stat\"><div class=\"tmc-stat-n\">Always</div><div class=\"tmc-stat-l\">On</div></div>\n  <div class=\"tmc-stat\"><div class=\"tmc-stat-n\">2s</div><div class=\"tmc-stat-l\">To reach you</div></div>\n</div>\n\n<!-- TMC_BRANDING trusted-by marquee -->\n<div class=\"tmc-trust\">\n  <div class=\"tmc-trust-track\">\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Masked calling</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Privacy by design</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> NFC + QR sticker</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> No app needed</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Masked calling</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Privacy by design</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> NFC + QR sticker</span>\n    <span class=\"tmc-trust-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2.2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> No app needed</span>\n  </div>\n</div>\n\n<div class=\"chev\"></div>\n\n<!-- THE PROBLEM  WHY YOU NEED THIS -->\n<div class=\"section\" id=\"why\">\n  <div class=\"section-label\">The problem</div>\n  <h2>Your car is vulnerable right now.</h2>\n  <p>Think about it  what happens when your car needs attention and you're not there?</p>\n  <div class=\"risk-grid\">\n    <div class=\"risk\">\n      <div class=\"risk-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></div>\n      <div><h3>Hit and run</h3><p>Someone damages your parked car. No way to reach you. They drive away.</p></div>\n    </div>\n    <div class=\"risk\">\n      <div class=\"risk-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07\"/><path d=\"M3.59 1.17A2 2 0 0 0 1.61 3.38 19.79 19.79 0 0 0 12 21a19.79 19.79 0 0 0 4.69-1.07\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg></div>\n      <div><h3>Number exposed</h3><p>You leave your phone number on the dashboard. Anyone can copy it, call you, or misuse it.</p></div>\n    </div>\n    <div class=\"risk\">\n      <div class=\"risk-icon\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg></div>\n      <div><h3>Towed away</h3><p>You're double-parked for 5 minutes. Nobody can warn you. Your car gets towed.</p></div>\n    </div>\n    <div class=\"risk\">\n      <div class=\"risk-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9\"/></svg></div>\n      <div><h3>Headlights on</h3><p>Battery drains overnight because no one could alert you in time.</p></div>\n    </div>\n  </div>\n  <a href=\"#solution\" class=\"learn-btn\">How TapMyCar solves this </a>\n</div>\n\n<div class=\"tape\"></div>\n\n<!-- THE SOLUTION -->\n<div class=\"section\" id=\"solution\" style=\"background:#F9FAFB\">\n  <div class=\"section-label\">The solution</div>\n  <h2>TapMyCar protects both.</h2>\n  <p>One smart tag on your car. Total privacy for you. Total safety for your vehicle.</p>\n  <div class=\"sol-grid\">\n    <div class=\"sol\">\n      <div class=\"sol-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\n      <div><h3>Your number stays hidden</h3><p>Every call is masked. Strangers never see your real phone number. Ever.</p></div>\n    </div>\n    <div class=\"sol\">\n      <div class=\"sol-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\"/></svg></div>\n      <div><h3>Instant contact</h3><p>Anyone scans your tag and reaches you in seconds. No app needed on their end.</p></div>\n    </div>\n    <div class=\"sol\">\n      <div class=\"sol-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg></div>\n      <div><h3>Every scan logged</h3><p>See who scanned, when, and where. Full awareness of your vehicle's activity.</p></div>\n    </div>\n    <div class=\"sol\">\n      <div class=\"sol-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg></div>\n      <div><h3>You screen every call</h3><p>Hear who's calling before you speak. Press 1 for auto-reply. Press 2 to connect.</p></div>\n    </div>\n  </div>\n</div>\n\n<!-- TMC_LAND_OBJECTIONS: address common concerns after seeing the solution -->\n<div class=\"chev\"></div>\n\n<div class=\"sec\">\n  <div class=\"sec-label\">Common questions</div>\n  <h2>What if someone abuses the system?</h2>\n  <p>Your real number stays hidden no matter what  so a stranger calling repeatedly never has a way to follow you outside TapMyCar.</p>\n  <div style=\"background:#F0F9FF;border:1px solid #BAE6FD;border-radius:14px;padding:16px;margin-top:14px;display:flex;gap:12px;align-items:flex-start\">\n    <div style=\"width:36px;height:36px;border-radius:10px;background:#E0F2FE;display:flex;align-items:center;justify-content:center;flex-shrink:0\">\n      <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0369A1\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/><polyline points=\"9 12 11 14 15 10\"/></svg>\n    </div>\n    <div>\n      <div style=\"font-size:14px;font-weight:800;color:#0C4A6E;margin-bottom:4px\">Worried about repeat calls or harassment?</div>\n      <div style=\"font-size:12px;color:#075985;line-height:1.6\">Every call is logged with timestamp and routed through a masked number. <strong>One tap blocks any number</strong>  the harasser can\\'t reach you again, and because they never had your real number to begin with, they can\\'t find you outside our system. You can screen first, decline, or report.</div>\n    </div>\n  </div>\n</div>\n\n<div class=\"sec\">\n  <div class=\"sec-label\">Built with tow operators in mind</div>\n  <h2>When your car is moved, you\\'re the first to know.</h2>\n  <p>Tow operators care about getting drivers reunited with their cars. With TapMyCar, that becomes effortless.</p>\n  <div style=\"background:#FFF7ED;border:1px solid #FED7AA;border-radius:14px;padding:16px;margin-top:14px;display:flex;gap:12px;align-items:flex-start\">\n    <div style=\"width:36px;height:36px;border-radius:10px;background:#FFE4CC;display:flex;align-items:center;justify-content:center;flex-shrink:0\">\n      <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9A3412\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 3h5v5\"/><path d=\"M21 3l-7 7\"/><path d=\"M3 21l7-7\"/><path d=\"M3 16v5h5\"/></svg>\n    </div>\n    <div>\n      <div style=\"font-size:14px;font-weight:800;color:#7C2D12;margin-bottom:4px\">Helping tow professionals do their job faster</div>\n      <div style=\"font-size:12px;color:#9A3412;line-height:1.6\">Tow operators tap your sticker and send a fast pre-filled message: <strong>where the car was taken, the lot address, and who to call</strong>. You get notified in seconds, not hours. <span style=\"color:#7C2D12;font-weight:700\">We partner with tow companies to make recoveries faster and less stressful  for everyone.</span></div>\n    </div>\n  </div>\n</div>\n\n<div class=\"chev\"></div>\n\n<!-- HOW IT WORKS -->\n<div class=\"section\">\n  <!-- TMC_HOWITWORKS_PHYSICAL -->\n  <div class=\"section-label\">How it works</div>\n  <h2>Simple as scan, call, done.</h2>\n  <p>Order your TapMyCar NFC sticker. Place it on your windshield. Stay reachable while your number stays hidden.</p>\n  <div class=\"steps\">\n    <div class=\"step\">\n      <div class=\"step-num\">1</div>\n      <div class=\"step-body\">\n        <h3>Order your TapMyCar sticker</h3>\n        <p>Pick Standard or Premium. Your physical NFC + QR sticker ships to your door within a few days.</p>\n      </div>\n    </div>\n    <div class=\"step\">\n      <div class=\"step-num\">2</div>\n      <div class=\"step-body\">\n        <h3>Stick it on your windshield</h3>\n        <p>Peel and place inside the windshield. Activates in seconds  no app needed for people scanning it.</p>\n      </div>\n    </div>\n    <div class=\"step\">\n      <div class=\"step-num\">3</div>\n      <div class=\"step-body\">\n        <h3>Someone scans  you get a private call</h3>\n        <p>A stranger taps their phone on the sticker or scans the QR. The call routes through TapMyCar  your real number is never shown.</p>\n      </div>\n    </div>\n    <div class=\"step\">\n      <div class=\"step-num\">4</div>\n      <div class=\"step-body\">\n        <h3>You decide what happens</h3>\n        <p>Hear who is calling first. Press 1 to send an auto-reply. Press 2 to speak directly. Decline anytime  you stay in full control.</p>\n      </div>\n    </div>\n  </div>\n\n  <div style=\"margin-top:24px;padding:16px 18px;background:#F9FAFB;border:1px solid #E5E7EB;border-radius:14px;cursor:pointer;transition:background .2s ease\" id=\"etag-toggle\" onclick=\"(function(){var b=document.getElementById('etag-box');var c=document.getElementById('etag-chev');var open=b.style.display==='block';b.style.display=open?'none':'block';c.style.transform=open?'rotate(0deg)':'rotate(180deg)';})()\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;gap:12px\">\n      <div>\n        <div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:2px\">Want the free digital eTag instead?</div>\n        <div style=\"font-size:12px;color:#6B7280\">No card needed. Get started in 2 minutes  perfect for trying it out.</div>\n      </div>\n      <svg id=\"etag-chev\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FF6B00\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:0 0 18px;transition:transform .25s ease\"><polyline points=\"6 9 12 15 18 9\"/></svg>\n    </div>\n    <div id=\"etag-box\" style=\"display:none;margin-top:14px;padding-top:14px;border-top:1px solid #E5E7EB\">\n      <div style=\"font-size:12px;color:#6B7280;line-height:1.6;margin-bottom:12px\">The eTag gives you a downloadable QR code you can print and stick anywhere. Calls still route through TapMyCar  your number stays hidden, just like the physical sticker.</div>\n      <div style=\"display:flex;flex-direction:column;gap:10px\">\n        <div style=\"display:flex;gap:10px;align-items:flex-start\">\n          <div style=\"flex:0 0 22px;height:22px;border-radius:50%;background:#FF6B00;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center\" class=\"etag-step-num\">1</div>\n          <div><div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:1px\">Sign up free</div><div style=\"font-size:12px;color:#6B7280\">No credit card. Pick the eTag plan during signup.</div></div>\n        </div>\n        <div style=\"display:flex;gap:10px;align-items:flex-start\">\n          <div style=\"flex:0 0 22px;height:22px;border-radius:50%;background:#FF6B00;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center\" class=\"etag-step-num\">2</div>\n          <div><div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:1px\">Download your QR</div><div style=\"font-size:12px;color:#6B7280\">Your unique TapMyCar QR is generated instantly. Print it on paper or a sticker.</div></div>\n        </div>\n        <div style=\"display:flex;gap:10px;align-items:flex-start\">\n          <div style=\"flex:0 0 22px;height:22px;border-radius:50%;background:#FF6B00;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center\" class=\"etag-step-num\">3</div>\n          <div><div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:1px\">Stick it on your windshield</div><div style=\"font-size:12px;color:#6B7280\">Any visible spot inside the windshield works. Anyone can scan it with a phone.</div></div>\n        </div>\n        <div style=\"display:flex;gap:10px;align-items:flex-start\">\n          <div style=\"flex:0 0 22px;height:22px;border-radius:50%;background:#FF6B00;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center\" class=\"etag-step-num\">4</div>\n          <div><div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:1px\">Receive private calls</div><div style=\"font-size:12px;color:#6B7280\">Same masked call system as the physical sticker. Your real number is never exposed.</div></div>\n        </div>\n      </div>\n      <a href=\"/pricing.html\" style=\"display:inline-block;margin-top:14px;font-size:12px;font-weight:700;color:#FF6B00;text-decoration:none\">Get the free eTag </a>\n    </div>\n  </div>\n\n</div>\n\n<div class=\"tape\"></div>\n\n<!-- APP DOWNLOAD BANNER -->\n<div class=\"app-banner\">\n  <div style=\"width:50px;height:50px;border-radius:14px;background:#FF6B00;margin:0 auto 12px;display:flex;align-items:center;justify-content:center\">\n    <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/><path d=\"M9 12l2 2 4-4\"/></svg>\n  </div>\n  <h3>Get the TapMyCar App</h3>\n  <p>Manage your tag, view scan history, control your privacy  all from your phone.</p>\n  <a href=\"/register.html\" data-tmc-cta=\"1\" class=\"app-btn\">Download Free </a>\n  <div class=\"app-sub\">Available on iOS, Android & Web  Free to start</div>\n</div>\n\n<!-- FEATURES -->\n<div class=\"section\" style=\"background:#F9FAFB\">\n  <div class=\"section-label\">Features</div>\n  <h2>Built for privacy and safety.</h2>\n  <div class=\"features-grid\">\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\n      <h3>Masked calls</h3>\n      <p>Your real number is never revealed to anyone.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/></svg></div>\n      <h3>QR + NFC tag</h3>\n      <p>Digital QR free. Physical NFC sticker ships on activation.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9\"/><path d=\"M13.73 21a2 2 0 0 1-3.46 0\"/></svg></div>\n      <h3>Scan alerts</h3>\n      <p>Get notified instantly when someone scans your tag.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\"/></svg></div>\n      <h3>Voice screening</h3>\n      <p>Screen calls before speaking to any stranger.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg></div>\n      <h3>Scan history</h3>\n      <p>See every scan with timestamp and location.</p>\n    </div>\n    <div class=\"feat\">\n      <div class=\"feat-icon\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg></div>\n      <h3>Always on</h3>\n      <p>Your tag works 24/7 even when your phone is off.</p>\n    </div>\n  </div>\n</div>\n\n<div class=\"chev\"></div>\n\n<!-- PRICING -->\n<div class=\"section\" style=\"background:#F9FAFB;padding:36px 24px\">\n  <div class=\"section-label\">See it in action</div>\n  <h2 style=\"margin-bottom:20px\">Watch how TapMyCar works.</h2>\n  <div data-tmc-reel=\"demo\" data-tmc-label=\"\"></div>\n</div>\n\n<div class=\"chev\"></div>\n\n<div class=\"section\">\n  <div class=\"section-label\">Pricing</div>\n  <h2>Start free. Upgrade when ready.</h2>\n  <p>No hidden fees. Cancel anytime before day 30.</p>\n\n  <div class=\"pricing-card\">\n    <div style=\"display:inline-block;background:#FF6B00;color:#fff;font-size:10px;font-weight:700;padding:3px 10px;border-radius:99px;margin-bottom:8px\">Most popular</div>\n    <h3>Standard</h3>\n    <div class=\"pricing-price\">$9.99 <span>+ $9.99/yr</span></div>\n    <div class=\"pricing-desc\">1 vehicle · physical NFC + QR sticker ships home</div>\n    <div class=\"pricing-features\">\n      <div class=\"pf\"><div class=\"pf-dot\"></div>Physical sticker ships to your home</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>10 masked calls per month</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>SMS alert on every scan</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>Voice screening system</div>\n    </div>\n    <a href=\"/register.html\" style=\"background:#FF6B00;color:#fff;font-size:14px;font-weight:700;padding:13px 0;border-radius:13px;text-decoration:none;display:block;text-align:center\" class=\"tmc-cta-orange\">Get Standard</a>\n  </div>\n\n  <div class=\"pricing-card\" style=\"border-color:#1A1A1A;background:#FAFAFA\">\n    <div style=\"display:inline-block;background:#1A1A1A;color:#fff;font-size:10px;font-weight:700;padding:3px 10px;border-radius:99px;margin-bottom:8px\">Best for families</div>\n    <h3>Premium</h3>\n    <div class=\"pricing-price\">$24.99 <span>+ $19.99/yr</span></div>\n    <div class=\"pricing-desc\">3 physical stickers · protect your whole family</div>\n    <div class=\"pricing-features\">\n      <div class=\"pf\"><div class=\"pf-dot\"></div>3 physical stickers (one-time purchase)</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>3 gift codes to share with family</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>Everything in Standard plan</div>\n      <div class=\"pf\"><div class=\"pf-dot\"></div>Priority support</div>\n    </div>\n    <a href=\"/register.html\" style=\"background:#1A1A1A;color:#fff;font-size:14px;font-weight:700;padding:13px 0;border-radius:13px;text-decoration:none;display:block;text-align:center\" class=\"tmc-cta-orange\">Get Premium</a>\n  </div>\n\n  <div style=\"background:#F0FDF4;border:1.5px solid #BBF7D0;border-radius:18px;padding:18px;margin-bottom:12px\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px\">\n      <div style=\"font-size:17px;font-weight:800;color:#111\">eTag</div>\n      <div style=\"background:#16A34A;color:#fff;font-size:11px;font-weight:700;padding:3px 12px;border-radius:99px\">Free</div>\n    </div>\n    <!-- TMC_PATCH64 -->\n    <div style=\"font-size:12px;color:#15803D;margin-bottom:6px\">Download instantly · Get started in 2 minutes</div>\n    <div style=\"font-size:11px;color:#6B7280;margin-bottom:14px;line-height:1.5\">Free to download. Activate for $1 to experience TapMyCar for 30 days; your chosen plan continues after — see <a href=\"/pricing.html\" style=\"color:#FF6B00\">pricing</a>.</div>\n    <a href=\"/register.html\" style=\"background:#16A34A;color:#fff;font-size:14px;font-weight:700;padding:13px 0;border-radius:13px;text-decoration:none;display:block;text-align:center\" class=\"tmc-cta-orange\">Get free eTag</a>\n  </div>\n\n  <div style=\"text-align:center;font-size:12px;color:#6B7280\">\n    <a href=\"/pricing.html\" style=\"color:#FF6B00;font-weight:600;text-decoration:none\">See all plans including Premium and Business </a>\n  </div>\n</div>\n\n<div class=\"tape\"></div>\n\n<!-- TESTIMONIAL -->\n<div class=\"section\" style=\"background:#fff;padding:36px 24px\">\n  <div class=\"section-label\">Real customers</div>\n  <h2 style=\"margin-bottom:20px\">Hear it from people using TapMyCar.</h2>\n  <div data-tmc-reel=\"review\" data-tmc-label=\"\"></div>\n</div>\n\n<div class=\"tape\"></div>\n\n<div class=\"section\" style=\"background:#F9FAFB\">\n  <div class=\"section-label\">Early users</div>\n  <h2>People love TapMyCar.</h2>\n  <div class=\"testimonial\">\n    <p>\"Someone left a note on my windshield asking me to move my car. I wish I had TapMyCar then  they could have just scanned and called me directly.\"</p>\n    <div class=\"test-author\">\n      <div class=\"test-av\">M</div>\n      <div>\n        <div class=\"test-name\">Mike R.</div>\n        <div class=\"test-sub\">Connecticut, USA</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class=\"chev\"></div>\n\n<!-- CTA -->\n<div class=\"cta\">\n  <h2>Your car deserves protection.</h2>\n  <p>Privacy for you. Safety for your car. Free to start  takes 2 minutes.</p>\n  <a href=\"/register.html\" data-tmc-cta=\"1\" class=\"cta-btn\">Explore TapMyCar</a>\n</div>\n\n<!-- APP DOWNLOAD STICKY -->\n<div style=\"background:#111;padding:16px 24px;display:flex;align-items:center;gap:12px\">\n  <div style=\"width:40px;height:40px;border-radius:10px;background:#FF6B00;display:flex;align-items:center;justify-content:center;flex-shrink:0\">\n    <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n  </div>\n  <div style=\"flex:1\">\n    <div style=\"font-size:13px;font-weight:700;color:#fff\">TapMyCar App</div>\n    <div style=\"font-size:10px;color:#9CA3AF\">Free  iOS, Android & Web</div>\n  </div>\n  <a href=\"/register.html\" data-tmc-cta=\"1\" style=\"background:#FF6B00;color:#fff;font-size:12px;font-weight:700;padding:8px 16px;border-radius:10px;text-decoration:none\">Get App</a>\n</div>\n\n<!-- TMC_PATCH26_APP_SETTINGS: landing.hero slot (download badges) -->\n<div data-tmc-slot=\"landing.hero\" style=\"padding:20px 24px 8px;display:flex;justify-content:center\"></div>\n\n<!-- TMC_PATCH26_APP_SETTINGS: landing.demo slot (demo video) -->\n<div data-tmc-slot=\"landing.demo\" style=\"padding:24px;display:flex;justify-content:center\"></div>\n\n<!-- FOOTER -->\n<!-- TMC_PATCH26_APP_SETTINGS: landing.footer slot (social + support) -->\n<div data-tmc-slot=\"landing.footer\" style=\"padding:14px 24px 0;text-align:center\"></div>\n<div class=\"footer\">\n  <p style=\"margin-bottom:6px\"><a href=\"/register.html\">Sign up</a> <span style=\"color:#D1D5DB;margin:0 6px\">|</span> <a href=\"/signin.html\">Sign in</a> <span style=\"color:#D1D5DB;margin:0 6px\">|</span> <a href=\"/pricing.html\">Pricing</a></p>\n  <p style=\"margin-bottom:6px\"><a href=\"/privacy.html\">Privacy Policy</a> <span style=\"color:#D1D5DB;margin:0 6px\">|</span> <a href=\"/terms.html\">Terms of Service</a></p>\n  <p> 2026 Praman Tech LLC  Connecticut, USA</p>\n</div>\n<script>\nif ('serviceWorker' in navigator) {\n  navigator.serviceWorker.register('/sw.js');\n}\n</script>\n<!-- TMC_PATCH26_APP_SETTINGS: settings renderer -->\n<script src=\"/app-settings.js\" defer></script>\n\n\n\n<script>\n// Dynamic testimonial loader - replaces fake Mike R. with most recent FEATURED review\n(async function() {\n  try {\n    const res = await fetch('/api/get-reviews?status=approved&landing_only=true&limit=1');\n    const data = await res.json();\n    if (!data.reviews || data.reviews.length === 0) return; // keep Mike R. fallback\n\n    const r = data.reviews[0];\n    const esc = s => String(s || '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n\n    // Find the testimonial container\n    const testContainer = document.querySelector('.testimonial');\n    if (!testContainer) return;\n\n    // 1. Replace the quote paragraph (first <p> child of .testimonial)\n    const quoteEl = testContainer.querySelector('p');\n    if (quoteEl) quoteEl.innerHTML = '&quot;' + esc(r.text) + '&quot;';\n\n    // 2. Replace the avatar letter\n    const avEl = testContainer.querySelector('.test-av');\n    if (avEl) avEl.textContent = (r.name || 'U')[0].toUpperCase();\n\n    // 3. Replace name\n    const nameEl = testContainer.querySelector('.test-name');\n    if (nameEl) nameEl.textContent = r.name;\n\n    // 4. Replace city/subtitle (if present)\n    const subEl = testContainer.querySelector('.test-sub');\n    if (subEl) subEl.textContent = r.city || 'Verified user';\n  } catch (e) {\n    // Silent - landing keeps Mike R. fallback\n  }\n})();\n</script>\n<script src=\"/app.js\"></script>\n<script src=\"/tmc-redesign.js\"></script>\n\n<script>\n// TMC_PATCH62_LANDING - logged-in visitors should not be pushed to register.\n(function(){\n  var token = null;\n  try { token = localStorage.getItem(\"tmc_token\"); } catch(e){}\n  if (!token) return;  // logged-out visitor: leave the page as-is\n  var ctas = document.querySelectorAll('a[data-tmc-cta=\"1\"]');\n  for (var i = 0; i < ctas.length; i++) {\n    ctas[i].setAttribute(\"href\", \"/dashboard.html\");\n    var t = (ctas[i].textContent || \"\").trim().toLowerCase();\n    // Relabel the wordy CTAs; leave tiny header buttons compact.\n    if (t.indexOf(\"explore\") !== -1 || t.indexOf(\"download\") !== -1) {\n      ctas[i].textContent = \"Go to Dashboard\";\n    } else {\n      ctas[i].textContent = \"Dashboard\";\n    }\n  }\n})();\n</script>\n<script src=\"/tmc-reels.js\"></script>\n<script>\n/* TMC_BRANDING_PRELOAD: avoid fallback flash via sessionStorage cache */\n(function(){\n  var KEY = 'tmc_hero_sticker_url';\n  var el = document.getElementById('tmc-hero-sticker');\n  if (!el) return;\n  try {\n    var cached = sessionStorage.getItem(KEY);\n    if (cached && cached !== 'null') {\n      el.innerHTML = '<img src=\"' + cached + '\" alt=\"TapMyCar sticker\">';\n    } else if (cached !== 'null') {\n      el.style.visibility = 'hidden';\n    }\n  } catch (e) {}\n  fetch('/api/get-branding').then(function(r){ return r.json(); }).then(function(d){\n    var url = (d && d.ok && d.sticker_url) ? d.sticker_url : null;\n    try { sessionStorage.setItem(KEY, url == null ? 'null' : url); } catch (e) {}\n    el.style.visibility = ''; el.classList.remove('tmc-pre-hidden');\n    if (url) {\n      var cur = el.querySelector('img');\n      if (!cur || cur.src !== url) el.innerHTML = '<img src=\"' + url + '\" alt=\"TapMyCar sticker\">';\n    }\n  }).catch(function(){ el.style.visibility = ''; el.classList.remove('tmc-pre-hidden'); });\n\n  /* Mouse-follow tilt on the sticker scene */\n  var scene = document.getElementById('tmc-hero-scene');\n  var sticker = document.getElementById('tmc-hero-sticker');\n  if (scene && sticker) {\n    var rect = null;\n    scene.addEventListener('mouseenter', function () { rect = scene.getBoundingClientRect(); sticker.style.transition = 'transform .15s ease-out'; });\n    scene.addEventListener('mousemove', function (e) {\n      if (!rect) rect = scene.getBoundingClientRect();\n      var cx = rect.left + rect.width / 2;\n      var cy = rect.top + rect.height / 2;\n      var dx = (e.clientX - cx) / (rect.width / 2);\n      var dy = (e.clientY - cy) / (rect.height / 2);\n      sticker.style.animation = 'none';\n      sticker.style.transform = 'rotateY(' + (dx * 35) + 'deg) rotateX(' + (-dy * 25) + 'deg) translateY(-4px) scale(1.05)';\n    });\n    scene.addEventListener('mouseleave', function () {\n      sticker.style.transition = 'transform .4s cubic-bezier(.2,.8,.2,1)';\n      sticker.style.transform = '';\n      sticker.style.animation = '';\n      rect = null;\n    });\n  }\n\n  /* Ripple on every CTA + step num */\n  function attachRipple(el) {\n    el.style.position = 'relative';\n    el.style.overflow = 'hidden';\n    el.addEventListener('click', function (e) {\n      var r = el.getBoundingClientRect();\n      var ripple = document.createElement('span');\n      var size = Math.max(r.width, r.height) * 2;\n      ripple.style.cssText = 'position:absolute;left:' + (e.clientX - r.left - size/2) + 'px;top:' + (e.clientY - r.top - size/2) + 'px;width:' + size + 'px;height:' + size + 'px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.55),transparent 65%);pointer-events:none;transform:scale(0);animation:tmcRipple .6s ease-out forwards;z-index:1';\n      el.appendChild(ripple);\n      setTimeout(function () { ripple.remove(); }, 650);\n    });\n  }\n  document.querySelectorAll('.hero-btn-primary, .hero-btn-secondary, .app-btn, .cta-btn, [data-tmc-cta]').forEach(attachRipple);\n\n  /* Inject ripple keyframes if not present */\n  if (!document.getElementById('tmc-ripple-style')) {\n    var st = document.createElement('style');\n    st.id = 'tmc-ripple-style';\n    st.textContent = '@keyframes tmcRipple { to { transform: scale(1); opacity: 0; } }\\n' +\n      '.hero-btn-primary, .hero-btn-secondary, .cta-btn, .app-btn, [data-tmc-cta] { transition: transform .2s ease, box-shadow .2s ease; }\\n' +\n      '.hero-btn-primary:hover, .cta-btn:hover { transform: translateY(-2px) scale(1.02); box-shadow: 0 14px 32px rgba(0,0,0,.22); }\\n' +\n      '.hero-btn-secondary:hover { transform: translateY(-2px); background: rgba(255,255,255,.25); }\\n' +\n      '.app-btn:hover { transform: translateY(-2px); box-shadow: 0 12px 28px rgba(255,107,0,.5); }\\n' +\n      '[data-tmc-cta]:hover { transform: translateY(-1px) scale(1.03); box-shadow: 0 6px 18px rgba(255,107,0,.45); }\\n' +\n      '.tmc-stat { transition: transform .2s ease; }\\n' +\n      '.tmc-stat:hover { transform: translateY(-3px); }\\n' +\n      '.tmc-stat:hover .tmc-stat-n { color: #FF8420; }\\n' +\n      '.step-num { transition: transform .25s cubic-bezier(.2,.8,.2,1); }\\n' +\n      '.step:hover .step-num { transform: scale(1.15) rotate(-6deg); }\\n' +\n      '.step { transition: transform .25s ease; }\\n' +\n      '.step:hover { transform: translateX(4px); }';\n    document.head.appendChild(st);\n  }\n})();\n\n/* TMC_COMIC: load + run slideshow */\n(function(){\n  fetch('/api/get-comic').then(function(r){ return r.json(); }).then(function(d){\n    var panels = (d && d.panels) || [];\n    var withImg = panels.filter(function(p){ return p && p.image_url; });\n    if (!withImg.length) return;\n    var section = document.getElementById('tmc-comic-section');\n    var panelsBox = document.getElementById('tmc-comic-panels');\n    var progBox = document.getElementById('tmc-comic-prog');\n    var dotsBox = document.getElementById('tmc-comic-dots');\n    if (!section || !panelsBox || !progBox || !dotsBox) return;\n    section.hidden = false;\n    function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;'); }\n    panelsBox.innerHTML = withImg.map(function(p, i){\n      return '<div class=\"tmc-comic-panel\">' +\n        '<div class=\"tmc-comic-art\">' +\n          '<img loading=\"lazy\" src=\"' + esc(p.image_url) + '\" alt=\"\">' +\n          '<div class=\"tmc-comic-overlay\"></div>' +\n          '<div class=\"tmc-comic-num\">FRAME ' + (i+1) + ' / ' + withImg.length + '</div>' +\n          '<div class=\"tmc-comic-cap\">' +\n            (p.title ? '<div class=\"tmc-comic-cap-t\">' + esc(p.title) + '</div>' : '') +\n            (p.caption ? '<div class=\"tmc-comic-cap-s\">' + esc(p.caption) + '</div>' : '') +\n          '</div>' +\n        '</div>' +\n      '</div>';\n    }).join('');\n    progBox.innerHTML = withImg.map(function(){ return '<div class=\"tmc-comic-prog-seg\"><div class=\"fill\"></div></div>'; }).join('');\n    dotsBox.innerHTML = withImg.map(function(_, i){ return '<button type=\"button\" class=\"tmc-comic-dot\" data-idx=\"' + i + '\" aria-label=\"Frame ' + (i+1) + '\"></button>'; }).join('');\n    var panelEls = panelsBox.querySelectorAll('.tmc-comic-panel');\n    var progEls = progBox.querySelectorAll('.tmc-comic-prog-seg');\n    var dotEls = dotsBox.querySelectorAll('.tmc-comic-dot');\n    var cur = 0, timer;\n    function go(i) {\n      cur = (i + panelEls.length) % panelEls.length;\n      panelEls.forEach(function(p, n){ p.classList.toggle('on', n === cur); });\n      dotEls.forEach(function(d, n){ d.classList.toggle('active', n === cur); });\n      progEls.forEach(function(s, n){\n        s.classList.remove('active','done');\n        if (n < cur) s.classList.add('done');\n        if (n === cur) s.classList.add('active');\n      });\n    }\n    function startT(){ clearInterval(timer); timer = setInterval(function(){ go(cur+1); }, 4500); }\n    go(0); startT();\n    document.getElementById('tmc-comic-prev').addEventListener('click', function(){ go(cur-1); startT(); });\n    document.getElementById('tmc-comic-next').addEventListener('click', function(){ go(cur+1); startT(); });\n    dotEls.forEach(function(d, i){ d.addEventListener('click', function(){ go(i); startT(); }); });\n    var startX = null;\n    var stage = document.getElementById('tmc-comic-stage');\n    stage.addEventListener('touchstart', function(e){ startX = e.touches[0].clientX; }, { passive: true });\n    stage.addEventListener('touchend', function(e){\n      if (startX === null) return;\n      var dx = e.changedTouches[0].clientX - startX; startX = null;\n      if (Math.abs(dx) > 40) { go(dx < 0 ? cur+1 : cur-1); startT(); }\n    });\n  }).catch(function(){});\n})();\n\n</script>\n</body>\n</html>\n", "public/manage.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <link rel=\"manifest\" href=\"/manifest.json\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"TapMyCar\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0\">\n<title>Manage tag — TapMyCar</title>\n<link rel=\"stylesheet\" href=\"/app.css\">\n<link rel=\"stylesheet\" href=\"/tmc-redesign.css\">\n<style>\n.plan-card{border-radius:16px;padding:18px;margin-bottom:12px;border:1.5px solid var(--bd)}\n.plan-card.current{border-color:var(--or);background:var(--orl)}\n.plan-badge{display:inline-block;font-size:9px;font-weight:700;padding:3px 10px;border-radius:99px;margin-bottom:8px}\n.plan-name{font-size:16px;font-weight:800;color:var(--bk);margin-bottom:2px}\n.plan-price{font-size:20px;font-weight:800;color:var(--or)}\n.plan-price span{font-size:12px;color:var(--gy);font-weight:400}\n.plan-feat{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--bk);margin-bottom:6px}\n.plan-feat-dot{width:5px;height:5px;border-radius:2px;background:var(--or);flex-shrink:0}\n.tag-detail{display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-bottom:.5px solid var(--bd)}\n.tag-detail:last-child{border-bottom:none}\n.tag-label{font-size:12px;color:var(--gy)}\n.tag-value{font-size:12px;font-weight:600;color:var(--bk)}\n</style>\n<!-- Favicon -->\n<link rel=\"icon\" type=\"image/x-icon\" href=\"/favicon.ico\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<!-- SEO -->\n<meta name=\"description\" content=\"Manage your TapMyCar tag settings and assignments.\">\n<meta name=\"author\" content=\"Praman Tech LLC\">\n<!-- Open Graph -->\n<meta property=\"og:title\" content=\"Manage tag — TapMyCar\">\n<meta property=\"og:description\" content=\"Manage your TapMyCar tag settings and assignments.\">\n<meta property=\"og:image\" content=\"https://tapmycar.io/og-image.png\">\n<meta property=\"og:url\" content=\"https://tapmycar.io/manage.html\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"TapMyCar\">\n<!-- Twitter Card -->\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Manage tag — TapMyCar\">\n<meta name=\"twitter:description\" content=\"Manage your TapMyCar tag settings and assignments.\">\n<meta name=\"twitter:image\" content=\"https://tapmycar.io/og-image.png\">\n</head>\n<body>\n<div class=\"nav\"><div class=\"bk\" onclick=\"tmcSmartBack()\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Manage Tag</span></div><div style=\"display:flex;align-items:center;gap:0\"><a href=\"/dashboard.html\" aria-label=\"TapMyCar\" style=\"display:flex;align-items:center;text-decoration:none\"><img src=\"/logo.png\" alt=\"TapMyCar\" class=\"nav-logo-img\" style=\"height:36px;width:auto;margin-right:10px\"></a><button class=\"gear\" onclick=\"window.location.href='/settings.html'\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"/></svg></button></div></div>\n<div class=\"chev\"></div>\n<div class=\"page\">\n<div class=\"page-inner\">\n\n  <!-- 1. SCAN TAG - MOST HIGHLIGHTED -->\n  <div style=\"background:linear-gradient(135deg,#FF6B00,#D21209);border-radius:18px;padding:20px 18px;margin-bottom:14px;position:relative;overflow:hidden\">\n    <div style=\"position:absolute;width:120px;height:120px;border-radius:50%;background:rgba(255,255,255,.08);right:-20px;top:-30px\"></div>\n    <div style=\"font-size:10px;font-weight:700;color:rgba(255,255,255,.75);margin-bottom:6px;letter-spacing:.8px;text-transform:uppercase\">Your physical tag</div>\n    <div style=\"font-size:20px;font-weight:800;color:#fff;line-height:1.3;margin-bottom:8px\">Scan. Contact. Protected.</div>\n    <div style=\"font-size:12px;color:rgba(255,255,255,.85);line-height:1.7;margin-bottom:14px\">Your NFC + QR sticker is your car's voice.<br><span style=\"color:#FFE4CC\">Strangers tap it - they reach you privately</span><br><span style=\"color:#FFE4CC\">Your real number is NEVER shared</span><br><span style=\"color:#FFE4CC\">You screen every call before answering</span></div>\n    <div style=\"display:flex;gap:8px\">\n      <button onclick=\"window.location.href='/activate.html'\" style=\"flex:1;background:#fff;color:#FF6B00;font-size:13px;font-weight:800;padding:12px 0;border-radius:12px;border:none;cursor:pointer;font-family:inherit\">Activate New Tag</button>\n      <button onclick=\"copyTagURL()\" style=\"flex:1;background:rgba(255,255,255,.2);color:#fff;font-size:13px;font-weight:700;padding:12px 0;border-radius:12px;border:1.5px solid rgba(255,255,255,.4);cursor:pointer;font-family:inherit\">Copy Tag URL</button>\n    </div>\n  </div>\n\n  <!-- 3. CURRENT PLAN -->\n  <div style=\"font-size:14px;font-weight:700;color:var(--bk);margin-bottom:10px\">Your Plan</div>\n  <div id=\"current-plan-box\"></div>\n\n\n  <!-- 2. CURRENT TAG INFO -->\n  <div class=\"card card-or\" style=\"margin-bottom:14px\">\n    <div style=\"display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px\">\n      <div>\n        <div style=\"font-size:16px;font-weight:700;color:var(--bk)\" id=\"m-vehicle\">My Vehicle</div>\n        <div style=\"font-size:11px;color:var(--gy);margin-top:2px;font-family:monospace\" id=\"m-token\">Loading...</div>\n      </div>\n      <span class=\"sp sp-on\" id=\"m-status\">Active</span>\n    </div>\n    <div id=\"m-details\">\n      <div class=\"tag-detail\"><span class=\"tag-label\">License plate</span><span class=\"tag-value\" id=\"m-plate\">-</span></div>\n      <div class=\"tag-detail\"><span class=\"tag-label\">Make</span><span class=\"tag-value\" id=\"m-make\">-</span></div>\n      <div class=\"tag-detail\"><span class=\"tag-label\">Model</span><span class=\"tag-value\" id=\"m-model\">-</span></div>\n      <div class=\"tag-detail\"><span class=\"tag-label\">Year</span><span class=\"tag-value\" id=\"m-year\">-</span></div>\n      <div class=\"tag-detail\"><span class=\"tag-label\">Color</span><span class=\"tag-value\" id=\"m-color\">-</span></div>\n      <div class=\"tag-detail\"><span class=\"tag-label\">Activated</span><span class=\"tag-value\" id=\"m-activated\">-</span></div>\n    </div>\n  </div>\n\n  <div id=\"upgraded-section\" style=\"display:none;background:var(--gnl);border:1.5px solid #BBF7D0;border-radius:14px;padding:16px;text-align:center;margin-bottom:12px\">\n    <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gn)\" stroke-width=\"2.5\" stroke-linecap=\"round\" style=\"margin-bottom:6px\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n    <div style=\"font-size:14px;font-weight:700;color:#166534;margin-bottom:4px\">You are on the <span id=\"upgraded-plan-name\">Standard</span> plan</div>\n    <div style=\"font-size:11px;color:#15803D\" id=\"another-tag-msg\">You have full access to all features.</div>\n  </div>\n\n\n  <!-- 4. ALL PLANS -->\n  <div data-available-plans-heading style=\"font-size:14px;font-weight:700;color:var(--bk);margin-bottom:10px\">Available Plans</div>\n\n  <div class=\"plan-card\" id=\"plan-standard\" style=\"border-color:var(--or);background:var(--orl)\">\n    <div class=\"plan-badge\" style=\"background:var(--or);color:#fff\">Most Popular</div>\n    <div class=\"plan-name\">Standard</div>\n    <div class=\"plan-price\">$9.99 <span>/yr</span></div>\n    <div style=\"font-size:11px;color:var(--gy);margin-bottom:12px\">Physical NFC + QR sticker ships to your door</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Physical weatherproof sticker shipped to you</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Know WHERE your car was scanned</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Screen every call before answering</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>SMS alert on every scan</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Your number NEVER shared</div>\n    <button class=\"btn\" id=\"btn-standard\" style=\"margin-top:12px;font-size:13px;padding:12px 0\" onclick=\"window.location.href='/pricing.html'\">Get Standard</button>\n  </div>\n\n  <div class=\"plan-card\" id=\"plan-premium\">\n    <div class=\"plan-badge\" style=\"background:#1A1A1A;color:#fff\">Family Protection</div>\n    <div class=\"plan-name\">Premium</div>\n    <div class=\"plan-price\">$19.99 <span>/yr</span></div>\n    <div style=\"font-size:11px;color:var(--gy);margin-bottom:12px\">Protect your whole family vehicles</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Everything in Standard</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Up to 3 vehicles covered</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Unlimited masked calls</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Scan location map</div>\n    <div class=\"plan-feat\"><div class=\"plan-feat-dot\"></div>Emergency contact feature</div>\n    <button class=\"btn\" id=\"btn-premium\" style=\"margin-top:12px;font-size:13px;padding:12px 0;background:#1A1A1A\" onclick=\"showUpgradeConfirm()\">Upgrade to Premium</button>\n  </div>\n\n  <div style=\"margin-bottom:14px;background:var(--gbl);border-radius:14px;padding:16px;border:.5px solid var(--bd)\">\n    <div style=\"font-size:13px;font-weight:700;color:var(--bk);margin-bottom:4px\">Need a tag for another car?</div>\n    <div style=\"font-size:11px;color:var(--gy);line-height:1.5;margin-bottom:10px\">Upgrade to Premium to protect up to 3 vehicles in your family.</div>\n    <a href=\"/pricing.html\" style=\"color:var(--or);font-size:12px;font-weight:700;text-decoration:none\">See all plans</a>\n  </div>\n\n  <!-- 5. FREE ETAG PDF - BOTTOM -->\n  <div style=\"background:#F9FAFB;border-radius:14px;padding:14px 16px;border:1px solid #E5E7EB;margin-bottom:14px;text-align:center\">\n    <div style=\"font-size:11px;color:#6B7280;margin-bottom:6px;text-transform:uppercase;letter-spacing:.5px;font-weight:700\">Free digital option</div>\n    <div style=\"font-size:12px;color:#374151;margin-bottom:10px;line-height:1.5\">No physical tag yet? Download a free digital eTag PDF to print and use temporarily.</div>\n    <button onclick=\"window.location.href='/etag.html'\" style=\"background:#fff;color:#FF6B00;font-size:12px;font-weight:700;padding:10px 20px;border-radius:10px;border:1.5px solid #FF6B00;cursor:pointer;font-family:inherit\">Download free eTag PDF</button>\n  </div>\n\n  <div style=\"background:#111;border-radius:14px;padding:14px 16px;display:flex;align-items:center;gap:12px;margin-bottom:14px\">\n    <div style=\"width:36px;height:36px;border-radius:9px;background:var(--or);display:flex;align-items:center;justify-content:center;flex-shrink:0\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\n    <div style=\"flex:1\"><div style=\"font-size:12px;font-weight:700;color:#fff\">Share TapMyCar</div><div style=\"font-size:10px;color:#9CA3AF\">Privacy for you. Safety for your car.</div></div>\n    <button onclick=\"navigator.share?navigator.share({title:'TapMyCar',text:'Privacy for you. Safety for your car.',url:'https://tapmycar.io'}):navigator.clipboard.writeText('https://tapmycar.io').then(()=>showToast('Link copied!'))\" style=\"background:var(--or);color:#fff;font-size:10px;font-weight:700;padding:6px 12px;border-radius:8px;border:none;cursor:pointer;font-family:Inter,sans-serif\">Share</button>\n  </div>\n\n</div>\n</div>\n\n<nav class=\"bnav\">\n  <a href=\"/dashboard.html\" class=\"bni\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><polyline points=\"9 22 9 12 15 12 15 22\"/></svg><span>Home</span></a>\n  <a href=\"/manage.html\" class=\"bni active\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/></svg><span>Tag</span><div class=\"bni-dot\"></div></a>\n  <a href=\"/activity.html\" class=\"bni\"><svg viewBox=\"0 0 24 24\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg><span>Activity</span></a>\n  <a href=\"/settings.html\" class=\"bni\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg><span>Profile</span></a>\n</nav>\n\n<div class=\"toast\" id=\"toast\"><div class=\"toast-ic\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><span id=\"toast-msg\"></span></div>\n\n<script src=\"/app.js\"></script>\n<script>\nrequireAuth();\nconst s = getSession();\nconst planNames = {etag:'eTag (Free)',standard:'Standard',premium:'Premium',business:'Business'};\nlet tagURL = '';\n\nasync function loadManage() {\n  try {\n    const res = await fetch('/api/get-dashboard?user_id=' + s.token);\n    const data = await res.json();\n    const userPlan = data.user ? (data.user.plan || 'etag') : 'etag';\n\n    if (data.tags && data.tags.length > 0) {\n      const tag = data.tags.find(t => t.status === 'active') || data.tags[0];\n      document.getElementById('m-vehicle').textContent = tag.vehicle_label || 'My Vehicle';\n      document.getElementById('m-token').textContent = tag.token.includes('-') ? tag.token : 'TMC-' + tag.token.replace(/^TMC[-.]?/,'');\n      document.getElementById('m-plate').textContent = tag.license_plate || '-';\n      document.getElementById('m-make').textContent = tag.car_make || '-';\n      document.getElementById('m-model').textContent = tag.car_model || '-';\n      document.getElementById('m-year').textContent = tag.car_year || '-';\n      document.getElementById('m-color').textContent = tag.car_color || '-';\n      const statusMap = {active:'sp-on',inactive:'sp-am',unclaimed:'sp-am',claimed:'sp-or',disabled:'sp-rd',paused:'sp-am'};\n      document.getElementById('m-status').className = 'sp ' + (statusMap[tag.status] || 'sp-am');\n      document.getElementById('m-status').textContent = tag.status.charAt(0).toUpperCase() + tag.status.slice(1);\n      if (tag.activated_at) {\n        document.getElementById('m-activated').textContent = new Date(tag.activated_at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});\n      }\n      tagURL = 'https://tapmycar.io/tag/' + tag.token;\n    }\n\n    /* TMC_PATCH35G_EXPIRED_DISPLAY: detect an expired gift tag. The user's plan is 'etag'\n       after expiry, but the tag still carries gift_expired + gift_plan,\n       so we show the real gift plan with a \"trial ended\" note. */\n    var _giftExpiredTag = null;\n    if (data.tags && data.tags.length) {\n      for (var _gi = 0; _gi < data.tags.length; _gi++) {\n        if (data.tags[_gi] && data.tags[_gi].gift_expired === true) {\n          _giftExpiredTag = data.tags[_gi];\n          break;\n        }\n      }\n    }\n\n    let planHTML = '<div class=\"plan-card current\" style=\"margin-bottom:14px\">';\n    if (_giftExpiredTag) {\n      var _gp = (_giftExpiredTag.gift_plan || 'standard');\n      var _gpName = planNames[_gp] || (_gp.charAt(0).toUpperCase() + _gp.slice(1));\n      planHTML += '<div class=\"plan-badge\" style=\"background:#DC2626;color:#fff\">Trial ended</div>';\n      planHTML += '<div class=\"plan-name\">' + _gpName + '</div>';\n      planHTML += '<div style=\"font-size:11px;color:var(--gy);margin-top:4px\">Your free trial has ended. Subscribe to reactivate your tag and keep ' + _gpName + ' features.</div>';\n    } else {\n      planHTML += '<div class=\"plan-badge\" style=\"background:var(--or);color:#fff\">Your Current Plan</div>';\n      planHTML += '<div class=\"plan-name\">' + (planNames[userPlan] || userPlan) + '</div>';\n      if (userPlan === 'etag') planHTML += '<div style=\"font-size:11px;color:var(--gy);margin-top:4px\">Free digital QR tag</div>';\n      else if (userPlan === 'standard') planHTML += '<div style=\"font-size:11px;color:var(--gy);margin-top:4px\">Physical sticker + masked calling + scan location</div>';\n      else if (userPlan === 'premium') planHTML += '<div style=\"font-size:11px;color:var(--gy);margin-top:4px\">3 vehicles + unlimited calls + full protection</div>';\n    }\n    planHTML += '</div>';\n    document.getElementById('current-plan-box').innerHTML = planHTML;\n\n    // Hide the user's current plan from \"Available Plans\" so only upgrades are shown\n    if (userPlan === 'standard') {\n      // On Standard → hide Standard card, show Premium as upgrade\n      document.getElementById('plan-standard').style.display = 'none';\n      document.getElementById('upgraded-section').style.display = 'block';\n      document.getElementById('upgraded-plan-name').textContent = 'Standard';\n      document.getElementById('another-tag-msg').textContent = 'Upgrade to Premium to protect up to 3 vehicles in your family.';\n    } else if (userPlan === 'premium') {\n      // On Premium → hide both (you're at the top)\n      document.getElementById('plan-standard').style.display = 'none';\n      document.getElementById('plan-premium').style.display = 'none';\n      document.getElementById('upgraded-section').style.display = 'block';\n      document.getElementById('upgraded-plan-name').textContent = 'Premium';\n      document.getElementById('another-tag-msg').textContent = 'You can protect up to 3 vehicles. Share Premium codes with family.';\n      // Also hide the \"Available Plans\" heading since nothing is available\n      const avHeading = document.querySelector('[data-available-plans-heading]');\n      if (avHeading) avHeading.style.display = 'none';\n    }\n    // Free plan users (etag) see both cards unchanged — they can upgrade to either\n  } catch(e) { console.error('Manage load error:', e); }\n}\n\nfunction copyTagURL() {\n  if (tagURL) {\n    navigator.clipboard.writeText(tagURL).then(() => showToast('Tag URL copied!')).catch(() => showToast('Copy failed'));\n  }\n}\n\n/* TMC_PATCH36UPGRADE_STD_TO_PREMIUM: start the Standard -> Premium upgrade checkout. */\nasync function p36StartUpgrade() {\n  var btn = document.getElementById('btn-premium');\n  var token = (typeof s !== 'undefined' && s && s.token) ? s.token : (localStorage.getItem('tmc_token') || '');\n  if (!token) { window.location.href = '/signin.html'; return; }\n  if (btn) { btn.disabled = true; btn.textContent = 'Loading...'; }\n  try {\n    var res = await fetch('/api/create-checkout', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ user_id: token, flow: 'upgrade', plan: 'premium' })\n    });\n    var data = await res.json();\n    if (data && data.url) { window.location.href = data.url; return; }\n    if (btn) { btn.disabled = false; btn.textContent = 'Upgrade to Premium'; }\n    alert((data && data.error) || 'Could not start the upgrade. Please try again.');\n  } catch (e) {\n    if (btn) { btn.disabled = false; btn.textContent = 'Upgrade to Premium'; }\n    alert('Network error. Please try again.');\n  }\n}\n\nloadManage();\n</script>\n<script>if ('serviceWorker' in navigator) { navigator.serviceWorker.register('/sw.js'); }</script>\n\n<div style=\"padding:20px 20px 32px;text-align:center;border-top:.5px solid #E5E7EB;margin-top:24px;background:#fff\">\n  <p style=\"font-size:11px;color:#9CA3AF;margin:0 0 4px\">\n    <a href=\"/privacy.html\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Privacy</a>\n    &nbsp;·&nbsp;\n    <a href=\"/terms.html\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Terms</a>\n    &nbsp;·&nbsp;\n    <a href=\"mailto:support@tapmycar.io\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Support</a>\n  </p>\n  <p style=\"font-size:11px;color:#9CA3AF;margin:0\">© 2026 Praman Tech LLC</p>\n</div>\n\n<script src=\"/tmc-redesign.js\"></script>\n\n<!-- TMC_FLOATING_NAV -->\n<nav class=\"tmc-fnav\" aria-label=\"Main navigation\">\n  <a href=\"/dashboard.html\" class=\"tmc-fnav-item\" data-match=\"/dashboard\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><polyline points=\"9 22 9 12 15 12 15 22\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Home</span>\n  </a>\n  <a href=\"/manage.html\" class=\"tmc-fnav-item\" data-match=\"/manage\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Tag</span>\n  </a>\n  <a href=\"/verify.html\" class=\"tmc-fnav-item\" data-match=\"/verify\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Verify</span>\n  </a>\n  <a href=\"/activity.html\" class=\"tmc-fnav-item\" data-match=\"/activity\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Activity</span>\n  </a>\n  <a href=\"/settings.html\" class=\"tmc-fnav-item\" data-match=\"/settings\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Profile</span>\n  </a>\n</nav>\n<!-- /TMC_FLOATING_NAV -->\n<script>\n/* TMC_SMART_BACK: keep back button context-aware. */\nwindow.tmcSmartBack = function () {\n  try {\n    if (document.referrer) {\n      var ref = new URL(document.referrer);\n      if (ref.origin === window.location.origin) {\n        var here = window.location.pathname.replace(/\\/+$/, '');\n        var refPath = ref.pathname.replace(/\\/+$/, '');\n        if (refPath !== here) {\n          window.history.back();\n          return;\n        }\n      }\n    }\n  } catch (e) {}\n  window.location.href = '/dashboard.html';\n};\n</script>\n<!-- TMC_UPGRADE_CONFIRM: confirm screen before Stripe redirect -->\n<div id=\"upg-overlay\" style=\"display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;align-items:flex-end;justify-content:center\" onclick=\"if(event.target===this)closeUpgradeConfirm()\">\n  <div style=\"background:#fff;border-radius:22px 22px 0 0;max-width:500px;width:100%;padding:24px 22px 28px;max-height:92vh;overflow-y:auto;font-family:Inter,sans-serif\">\n    <div style=\"width:42px;height:4px;background:#E5E7EB;border-radius:2px;margin:0 auto 18px\"></div>\n    <div style=\"font-size:11px;font-weight:700;color:#FF6B00;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">Upgrade to Premium</div>\n    <div style=\"font-size:22px;font-weight:800;color:#111;letter-spacing:-.5px;margin-bottom:6px\">3 stickers for your household</div>\n    <div style=\"font-size:13px;color:#6B7280;line-height:1.55;margin-bottom:18px\">Protect every car your family drives with the same TapMyCar privacy.</div>\n    <div style=\"background:#FFF7ED;border:1px solid #FED7AA;border-radius:14px;padding:14px;margin-bottom:14px\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;font-size:13px;color:#7C2D12;margin-bottom:8px\">\n        <span>You have today</span>\n        <span style=\"font-weight:700\">1 Standard sticker</span>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;align-items:center;font-size:13px;color:#7C2D12;margin-bottom:8px\">\n        <span>You\\'ll receive</span>\n        <span style=\"font-weight:700\">2 more stickers</span>\n      </div>\n      <div style=\"height:1px;background:#FED7AA;margin:10px 0\"></div>\n      <div style=\"display:flex;justify-content:space-between;align-items:center;font-size:14px;color:#7C2D12\">\n        <span style=\"font-weight:700\">After upgrade</span>\n        <span style=\"font-weight:800;color:#9A3412\">3 Premium stickers</span>\n      </div>\n    </div>\n    <div style=\"background:#F9FAFB;border:1px solid #E5E7EB;border-radius:14px;padding:14px;margin-bottom:14px\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;font-size:13px;color:#374151;margin-bottom:10px\">\n        <span>Charge today (one-time)</span>\n        <span style=\"font-weight:800;color:#111;font-size:18px\">$14.99</span>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#6B7280;margin-bottom:8px\">\n        <span>Current annual plan</span>\n        <span style=\"text-decoration:line-through;color:#9CA3AF\">$9.99/yr</span>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#6B7280\">\n        <span>New annual plan (next renewal)</span>\n        <span style=\"font-weight:700;color:#111\">$19.99/yr</span>\n      </div>\n    </div>\n    <div style=\"background:#fff;border:1px solid #E5E7EB;border-radius:14px;padding:14px;margin-bottom:18px\">\n      <div style=\"font-size:11px;font-weight:700;color:#6B7280;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px\">What you get</div>\n      <div style=\"font-size:13px;color:#111;line-height:1.8\">\n        <div style=\"display:flex;align-items:center;gap:8px\"><span style=\"color:#16A34A;font-weight:800\">✓</span> 2 extra stickers ship in 2-3 business days</div>\n        <div style=\"display:flex;align-items:center;gap:8px\"><span style=\"color:#16A34A;font-weight:800\">✓</span> Up to 3 family vehicles protected</div>\n        <div style=\"display:flex;align-items:center;gap:8px\"><span style=\"color:#16A34A;font-weight:800\">✓</span> 3 gift codes to share with family</div>\n        <div style=\"display:flex;align-items:center;gap:8px\"><span style=\"color:#16A34A;font-weight:800\">✓</span> Priority support</div>\n      </div>\n    </div>\n    <div style=\"font-size:11px;color:#9CA3AF;line-height:1.55;margin-bottom:14px\">Your card is charged $14.99 today. The new $19.99/year Premium plan begins on your next renewal date, replacing your $9.99/year Standard plan. Refundable within 14 days minus a $1 service fee. Cancel anytime in Settings.</div>\n    <button id=\"upg-confirm-btn\" type=\"button\" onclick=\"confirmUpgradeAndPay()\" style=\"width:100%;background:#FF6B00;color:#fff;border:0;border-radius:13px;padding:15px 0;font-size:15px;font-weight:800;cursor:pointer;font-family:inherit;box-shadow:0 8px 20px rgba(255,107,0,.35)\">Confirm and pay $14.99</button>\n    <button type=\"button\" onclick=\"closeUpgradeConfirm()\" style=\"width:100%;background:transparent;color:#6B7280;border:0;padding:14px 0 0;font-size:13px;font-weight:600;cursor:pointer;font-family:inherit\">Cancel</button>\n  </div>\n</div>\n<script>\n/* TMC_UPGRADE_CONFIRM */\nfunction showUpgradeConfirm() {\n  var ov = document.getElementById('upg-overlay');\n  if (!ov) return;\n  ov.style.display = 'flex';\n  document.body.style.overflow = 'hidden';\n}\nfunction closeUpgradeConfirm() {\n  var ov = document.getElementById('upg-overlay');\n  if (!ov) return;\n  ov.style.display = 'none';\n  document.body.style.overflow = '';\n}\nasync function confirmUpgradeAndPay() {\n  var btn = document.getElementById('upg-confirm-btn');\n  if (btn) { btn.disabled = true; btn.textContent = 'Opening checkout…'; }\n  try { if (typeof p36StartUpgrade === 'function') { await p36StartUpgrade(); } }\n  catch (e) {\n    if (btn) { btn.disabled = false; btn.textContent = 'Confirm and pay $14.99'; }\n  }\n}\n</script>\n</body>\n</html>", "public/help.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<title>Help & FAQ — TapMyCar</title>\n<meta name=\"description\" content=\"Frequently asked questions about TapMyCar — billing, your sticker, calls, privacy, and more.\">\n\n<link rel=\"icon\" href=\"/favicon.ico\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"manifest\" href=\"/manifest.json\">\n<link rel=\"stylesheet\" href=\"/app.css\">\n\n<style>\n.help-page { max-width: 720px; margin: 0 auto; padding: 24px 16px 80px; }\n.help-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }\n.help-h1 { font-size: 28px; font-weight: 800; color: #111; letter-spacing: -.5px; margin: 0 0 6px; }\n.help-sub { font-size: 14px; color: #6B7280; line-height: 1.55; margin: 0 0 22px; }\n.help-search { position: relative; margin: 0 0 24px; }\n.help-search input {\n  width: 100%; padding: 13px 14px 13px 42px; font-size: 14px;\n  border: 1.5px solid #E5E7EB; border-radius: 12px;\n  background: #fff; color: #111; font-family: inherit;\n  -webkit-appearance: none; appearance: none; box-sizing: border-box;\n  transition: border-color .2s ease, box-shadow .2s ease;\n}\n.help-search input:focus { outline: none; border-color: #FF6B00; box-shadow: 0 0 0 4px rgba(255,107,0,.1); }\n.help-search svg { position: absolute; left: 14px; top: 50%; transform: translateY(-50%); width: 18px; height: 18px; color: #9CA3AF; pointer-events: none; }\n.help-section { margin: 0 0 22px; }\n.help-section-h { font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .12em; color: #FF6B00; margin: 0 0 10px; padding: 0 4px; }\n.help-item {\n  background: #fff; border: 1px solid #E5E7EB; border-radius: 12px;\n  margin: 0 0 8px; overflow: hidden;\n  transition: border-color .2s ease, box-shadow .25s ease;\n}\n.help-item:hover { border-color: #FED7AA; }\n.help-item.open { border-color: #FF6B00; box-shadow: 0 6px 18px rgba(255,107,0,.1); }\n.help-q {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 14px 16px; cursor: pointer;\n  font-size: 14px; font-weight: 700; color: #111; line-height: 1.4;\n  gap: 12px; -webkit-tap-highlight-color: transparent;\n}\n.help-q-chev { width: 18px; height: 18px; color: #FF6B00; flex: 0 0 18px; transition: transform .25s ease; }\n.help-item.open .help-q-chev { transform: rotate(180deg); }\n.help-a {\n  max-height: 0; overflow: hidden;\n  transition: max-height .35s ease, padding .25s ease;\n  padding: 0 16px; font-size: 13px; color: #4B5563; line-height: 1.65;\n}\n.help-item.open .help-a { max-height: 600px; padding: 0 16px 14px; }\n.help-a p { margin: 0 0 8px; }\n.help-a p:last-child { margin: 0; }\n.help-a a { color: #FF6B00; font-weight: 600; text-decoration: none; }\n.help-a a:hover { text-decoration: underline; }\n.help-a ul { margin: 6px 0 8px; padding: 0 0 0 18px; }\n.help-a li { margin: 0 0 4px; }\n.help-a strong { color: #111; font-weight: 700; }\n.help-noresults { text-align: center; padding: 28px 12px; color: #9CA3AF; font-size: 13px; display: none; }\n.help-noresults.show { display: block; }\n\n.help-contact {\n  margin: 28px 0 0; padding: 20px;\n  background: linear-gradient(135deg, #FFF7ED 0%, #FFE4CC 100%);\n  border: 1px solid #FED7AA; border-radius: 14px;\n  text-align: center;\n}\n.help-contact-h { font-size: 15px; font-weight: 800; color: #7C2D12; margin: 0 0 4px; }\n.help-contact-s { font-size: 12px; color: #9A3412; margin: 0 0 14px; line-height: 1.55; }\n.help-contact a {\n  display: inline-flex; align-items: center; gap: 8px;\n  background: #FF6B00; color: #fff;\n  font-size: 13px; font-weight: 700;\n  padding: 11px 18px; border-radius: 10px;\n  text-decoration: none;\n  box-shadow: 0 6px 16px rgba(255,107,0,.3);\n  transition: transform .15s ease, box-shadow .15s ease;\n}\n.help-contact a:active { transform: translateY(1px); box-shadow: 0 3px 8px rgba(255,107,0,.3); }\n</style>\n</head>\n\n<body class=\"wide-page\">\n<div class=\"help-page\">\n\n  <div class=\"help-hdr\">\n    <a href=\"/\" aria-label=\"TapMyCar\"><img src=\"/logo.png\" alt=\"TapMyCar\" style=\"height:44px;width:auto;display:block\"></a>\n    <a href=\"javascript:void(0)\" onclick=\"tmcSmartBack('/')\" class=\"back-link\" style=\"margin:0\">← Back</a>\n  </div>\n\n  <h1 class=\"help-h1\">Help & FAQ</h1>\n  <p class=\"help-sub\">Quick answers about how TapMyCar works, billing, your sticker, and your privacy. Tap any question to expand. Still stuck? Email us — link at the bottom.</p>\n\n  <div class=\"help-search\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n    <input type=\"search\" id=\"help-q-input\" placeholder=\"Search questions…\" autocomplete=\"off\">\n  </div>\n\n  <div id=\"help-list\">\n\n    <!-- GETTING STARTED -->\n    <div class=\"help-section\" data-section=\"Getting started\">\n      <div class=\"help-section-h\">Getting started</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What is TapMyCar?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>TapMyCar is a privacy-first contact platform for your vehicle. You stick a small NFC + QR sticker on your windshield. If someone needs to reach you about your car — for example to ask you to move it, or to report damage — they tap or scan the sticker and call you through our system. <strong>Your real phone number stays hidden</strong> the entire time.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How do I get started?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Two ways:</p><ul><li><strong>Free eTag</strong> — sign up, download your digital tag, and try TapMyCar without a card.</li><li><strong>Physical sticker</strong> — pick Standard or Premium on the <a href=\"/pricing.html\">pricing page</a>. Your sticker ships in 2–3 business days.</li></ul></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Do I need an app?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>No. TapMyCar works in any modern phone browser. You manage your tag, calls, and settings from <a href=\"/dashboard.html\">tapmycar.io</a>. Strangers scanning your sticker don't need an app either — the NFC tap or QR scan opens the call page directly.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Does it work on iPhone and Android?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes, both. iPhones (iOS 14 and newer) and Android phones can read the NFC tag with a normal tap. Older devices can still use the QR code printed on every sticker. No app install needed on either side.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Is there a free version?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes — the <strong>eTag</strong> is free to download and works the same way the sticker does: masked calls, screening, your number stays hidden. You can print it or display it however you like. The eTag becomes active for $1 so we can route calls; physical stickers add the actual sticker shipped to your door.</p></div></div>\n    </div>\n\n    <!-- YOUR STICKER -->\n    <div class=\"help-section\" data-section=\"Your sticker\">\n      <div class=\"help-section-h\">Your sticker</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What's in the sticker?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Each sticker has a small embedded NFC chip <strong>and</strong> a printed QR code. Both link to your private call page. The sticker is weatherproof, designed to live on the inside of your windshield.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Where should I put the sticker?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>The inside of your windshield, lower passenger-side corner is the most common spot. Some people place it on the driver-side dashboard. The key is that it's visible to anyone standing outside the car and that the QR + NFC area isn't blocked.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How long does shipping take?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Physical stickers ship within 2–3 business days. We mail in the US only at the moment.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Can I have stickers on more than one car?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes. The <strong>Premium</strong> plan ships 3 stickers — handy if you have multiple vehicles, share a household, or want a spare. Each sticker is linked to your single account so all calls go to you.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What if my sticker is damaged or stolen?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Email <a href=\"mailto:support@tapmycar.io\">support@tapmycar.io</a> and we'll deactivate the missing tag and send a replacement. Even if someone steals the sticker, your real phone number never goes with it — they only get a routing link that we can revoke.</p></div></div>\n    </div>\n\n    <!-- HOW CALLS WORK -->\n    <div class=\"help-section\" data-section=\"How calls work\">\n      <div class=\"help-section-h\">How calls work</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What happens when someone scans my sticker?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>The scanner is taken to a simple page on their phone with a \"Call owner\" button. When they tap it, our system places a masked call through to you. They never see your real number, and you can decide whether to answer.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Does the caller ever see my real phone number?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p><strong>No.</strong> Every call is routed through a TapMyCar number. The other person only sees that intermediate number — never yours. You also can't be reached at your real number by anyone who has just the sticker.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Can I screen calls before answering?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes. Every incoming TapMyCar call lets you screen who's calling before you pick up. You can answer, decline, or let it go to voicemail — your choice, every time.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Do I get notified when someone scans my sticker?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes. Every scan shows up in your dashboard in real time with timestamp and approximate location (if the scanner allows). If they place a call, you also get the call right then. You can review your scan history any time from the <a href=\"/activity.html\">activity page</a>.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What if I'm not available to answer?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>The call simply goes unanswered, like any phone call. The scan still gets logged in your dashboard so you can see who tried to reach you and when. We do not relay text messages to your real phone number.</p></div></div>\n    </div>\n\n    <!-- BILLING -->\n    <div class=\"help-section\" data-section=\"Billing & plans\">\n      <div class=\"help-section-h\">Billing & plans</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How much does TapMyCar cost?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p><strong>Free eTag:</strong> free to download. $1 activation to enable masked calls.</p><p><strong>Standard:</strong> $9.99 for the sticker (shipped immediately) and then $9.99/year starting on day 30. Renews yearly.</p><p><strong>Premium:</strong> $24.99 for 3 stickers and then $19.99/year starting on day 30. Renews yearly.</p><p>Full details on the <a href=\"/pricing.html\">pricing page</a>.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">When does my annual subscription start?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>On day 30 after you pick a paid plan. That gives you a full month to try TapMyCar before the annual fee kicks in. You can cancel any time before day 30 in <a href=\"/settings.html\">Settings</a> and you'll only have paid the sticker fee.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How do I cancel?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Go to <a href=\"/billing.html\">Plan & Billing</a> in your Settings and tap \"Cancel plan.\" You stay active until the end of the period you've already paid for — no surprise cutoffs.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What's your refund policy?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Refunds available within 14 days of any annual charge — a $1 service fee is retained. After 14 days the plan is non-refundable for that period. Activation fees and sticker fees are non-refundable. Cancel anytime to stop future charges.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Can I upgrade from Standard to Premium?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><!-- TMC_FAQ_UPGRADE_PRICE --><p>Yes. From <a href=\"/manage.html\">Manage Tags</a>, tap <strong>Upgrade to Premium</strong>. You'll see a confirmation screen, then a <strong>flat $14.99 charge</strong> covers the upgrade. We ship 2 more stickers so you have 3 total. Your next annual renewal moves from $9.99/yr (Standard) to $19.99/yr (Premium). Your existing sticker keeps working.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Do you accept which payment methods?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>All major credit and debit cards, plus Apple Pay and Google Pay where supported. Payments are processed securely by Stripe — we never see or store your full card details.</p></div></div>\n    </div>\n\n    <!-- PRIVACY & SAFETY -->\n    <div class=\"help-section\" data-section=\"Privacy & safety\">\n      <div class=\"help-section-h\">Privacy & safety</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Who can see my phone number?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Only TapMyCar (so we can route calls to you). Not strangers who scan your sticker, not other users, not anyone else. Calls are masked at the carrier level — your number is never transmitted to the caller.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What data do you collect?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Only what's needed to run the service: your phone number, sign-in email, billing details (handled by Stripe), and a log of scans and calls on your sticker so you can see your activity. Full details in our <a href=\"/privacy.html\">Privacy Policy</a>.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Do you share or sell my information?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>No. We don't sell your data and we don't share it for advertising. The only third parties we share with are the service providers that help us run TapMyCar — Twilio for masked calls, Stripe for payments, etc. See the <a href=\"/privacy.html\">Privacy Policy</a> for the full list.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Is the call recorded?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>No. We do not record or transcribe TapMyCar calls. We log only the call metadata (timestamp, masked number used, duration) so you can see your call history.</p></div></div>\n    </div>\n\n    <!-- ACCOUNT & TROUBLESHOOTING -->\n    <div class=\"help-section\" data-section=\"Account & troubleshooting\">\n      <div class=\"help-section-h\">Account & troubleshooting</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">I changed my phone number — what do I do?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Go to <a href=\"/settings.html\">Settings</a> and update your phone number. You'll be asked to verify the new number with an SMS code. Once verified, all your existing stickers route calls to the new number automatically — you don't need new stickers.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">The NFC tap isn't working — what should I check?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Make sure the phone's NFC is turned on (on iPhone it's always on; on Android check Settings → Connected devices → NFC). Hold the back of the phone <strong>directly</strong> on the sticker for 1–2 seconds. If the tap still doesn't trigger, the QR code on the same sticker is a 100% reliable fallback — just open your camera and point it at the QR.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">I have a referral code — how does it work?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Each TapMyCar account has a referral code (visible in <a href=\"/settings.html\">Settings</a>). Share it with a friend; when they sign up and activate, both of you get a credit applied to your account. Credits reduce future charges automatically at checkout.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">I forgot my password / can't sign in.<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>TapMyCar uses passwordless sign-in. On the <a href=\"/signin.html\">sign-in page</a>, enter your phone number — we'll text you a code to log in. If you can't receive the code, email <a href=\"mailto:support@tapmycar.io\">support@tapmycar.io</a> from the email on your account.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How do I delete my account?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Email <a href=\"mailto:support@tapmycar.io\">support@tapmycar.io</a> from your account email and we'll permanently delete your account, stickers, and call history within 7 days. You can request a copy of your data first if you want.</p></div></div>\n    </div>\n\n  </div>\n\n  <div class=\"help-noresults\" id=\"help-noresults\">\n    No questions match your search. Try a different word, or email us below.\n  </div>\n\n  <div class=\"help-contact\">\n    <div class=\"help-contact-h\">Didn't find what you needed?</div>\n    <div class=\"help-contact-s\">We answer every email, usually within one business day.</div>\n    <a href=\"mailto:support@tapmycar.io\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M4 4h16a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z\"/><polyline points=\"22 6 12 13 2 6\"/></svg>\n      Email support@tapmycar.io\n    </a>\n  </div>\n\n</div>\n\n<script>\n/* TMC_SMART_BACK: context-aware back navigation. */\nwindow.tmcSmartBack = function (fallback) {\n  fallback = fallback || '/dashboard.html';\n  try {\n    if (document.referrer) {\n      var ref = new URL(document.referrer);\n      if (ref.origin === window.location.origin) {\n        var here = window.location.pathname.replace(/\\/+$/, '');\n        var refPath = ref.pathname.replace(/\\/+$/, '');\n        if (refPath !== here) { window.history.back(); return; }\n      }\n    }\n  } catch (e) {}\n  window.location.href = fallback;\n};\n\n/* FAQ: accordion + search */\n(function () {\n  var items = document.querySelectorAll('.help-item');\n  items.forEach(function (item) {\n    var q = item.querySelector('.help-q');\n    q.addEventListener('click', function () { item.classList.toggle('open'); });\n  });\n\n  var input = document.getElementById('help-q-input');\n  var noResults = document.getElementById('help-noresults');\n  var sections = document.querySelectorAll('.help-section');\n\n  input.addEventListener('input', function () {\n    var q = (input.value || '').trim().toLowerCase();\n    var anyVisible = false;\n    sections.forEach(function (sec) {\n      var sectionHasMatch = false;\n      sec.querySelectorAll('.help-item').forEach(function (item) {\n        var text = item.textContent.toLowerCase();\n        var match = !q || text.indexOf(q) !== -1;\n        item.style.display = match ? '' : 'none';\n        if (match) { sectionHasMatch = true; anyVisible = true; }\n        if (q && match) { item.classList.add('open'); }\n        else if (!q) { item.classList.remove('open'); }\n      });\n      sec.style.display = sectionHasMatch ? '' : 'none';\n    });\n    noResults.classList.toggle('show', q && !anyVisible);\n  });\n})();\n</script>\n</body>\n</html>\n", "public/business.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<!-- TMC_BUSINESS_INQUIRY -->\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<title>Business / Fleet — TapMyCar</title>\n<meta name=\"description\" content=\"Bulk TapMyCar stickers with your business name printed on every tag. Custom branding for fleets, dealerships, rentals, and more.\">\n<link rel=\"icon\" href=\"/favicon.ico\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"manifest\" href=\"/manifest.json\">\n<link rel=\"stylesheet\" href=\"/app.css\">\n<style>\n.biz { max-width: 560px; margin: 0 auto; padding: 22px 16px 80px; }\n.biz-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }\n.biz-h1 { font-size: 28px; font-weight: 800; letter-spacing: -.5px; color: #111; margin: 0 0 6px; }\n.biz-sub { font-size: 14px; color: #6B7280; line-height: 1.6; margin: 0 0 24px; }\n.biz-feat { display: grid; grid-template-columns: repeat(2,1fr); gap: 10px; margin: 0 0 28px; }\n.biz-feat-card { background: #FFF7ED; border: 1px solid #FED7AA; border-radius: 13px; padding: 14px; }\n.biz-feat-card h4 { font-size: 13px; font-weight: 800; color: #7C2D12; margin: 0 0 4px; }\n.biz-feat-card p { font-size: 11px; color: #9A3412; line-height: 1.55; margin: 0; }\n.biz-form { background: #fff; border: 1px solid #E5E7EB; border-radius: 16px; padding: 20px; }\n.biz-form h3 { font-size: 16px; font-weight: 800; color: #111; margin: 0 0 4px; }\n.biz-form p.intro { font-size: 12px; color: #6B7280; margin: 0 0 18px; line-height: 1.55; }\n.biz-row { margin: 0 0 14px; }\n.biz-label { display: block; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; letter-spacing: .04em; margin: 0 0 6px; }\n.biz-input, .biz-textarea {\n  width: 100%; padding: 12px 14px; font-size: 14px;\n  border: 1.5px solid #E5E7EB; border-radius: 11px;\n  background: #fff; color: #111; font-family: inherit;\n  -webkit-appearance: none; appearance: none; box-sizing: border-box;\n  transition: border-color .2s ease, box-shadow .2s ease;\n}\n.biz-input:focus, .biz-textarea:focus { outline: none; border-color: #FF6B00; box-shadow: 0 0 0 4px rgba(255,107,0,.1); }\n.biz-textarea { resize: vertical; min-height: 90px; line-height: 1.5; }\n.biz-help { font-size: 11px; color: #9CA3AF; margin: 6px 0 0; line-height: 1.5; }\n.biz-logo-drop {\n  border: 1.5px dashed #E5E7EB; border-radius: 11px; padding: 18px 14px;\n  text-align: center; cursor: pointer; transition: border-color .2s ease, background .2s ease;\n}\n.biz-logo-drop:hover { border-color: #FF6B00; background: #FFF7ED; }\n.biz-logo-drop.has-file { border-color: #16A34A; background: #F0FDF4; border-style: solid; }\n.biz-logo-drop input { display: none; }\n.biz-logo-drop p { font-size: 12px; color: #6B7280; margin: 0; line-height: 1.55; }\n.biz-logo-preview { display: none; max-width: 140px; max-height: 140px; margin: 8px auto 0; border-radius: 8px; }\n.biz-submit {\n  width: 100%; background: #FF6B00; color: #fff;\n  font-size: 15px; font-weight: 800; padding: 15px 0;\n  border: 0; border-radius: 13px; cursor: pointer;\n  box-shadow: 0 8px 22px rgba(255,107,0,.35);\n  transition: transform .15s ease, box-shadow .15s ease;\n  font-family: inherit;\n}\n.biz-submit:active { transform: translateY(2px); box-shadow: 0 4px 12px rgba(255,107,0,.3); }\n.biz-submit:disabled { opacity: .55; cursor: not-allowed; }\n.biz-err { font-size: 12px; color: #DC2626; margin: 10px 0 0; line-height: 1.5; }\n.biz-ok-card { display: none; background: linear-gradient(135deg, #F0FDF4 0%, #DCFCE7 100%); border: 1px solid #BBF7D0; border-radius: 16px; padding: 28px 22px; text-align: center; }\n.biz-ok-card h3 { font-size: 20px; font-weight: 800; color: #166534; margin: 0 0 8px; }\n.biz-ok-card p { font-size: 13px; color: #15803D; line-height: 1.65; margin: 0; }\n</style>\n</head>\n<body class=\"wide-page\">\n<div class=\"biz\">\n  <div class=\"biz-hdr\">\n    <a href=\"/\" aria-label=\"TapMyCar\"><img src=\"/logo.png\" alt=\"TapMyCar\" style=\"height:44px;width:auto;display:block\"></a>\n    <a href=\"javascript:void(0)\" onclick=\"tmcSmartBack('/pricing.html')\" class=\"back-link\" style=\"margin:0\">← Back</a>\n  </div>\n\n  <h1 class=\"biz-h1\">Business / Fleet</h1>\n  <p class=\"biz-sub\">Bulk TapMyCar stickers with <strong>your business name printed on every tag</strong>. Perfect for fleets, dealerships, car rentals, ride-share teams, and corporate vehicle programs.</p>\n\n  <div class=\"biz-feat\">\n    <div class=\"biz-feat-card\"><h4>Custom branding</h4><p>Your business name printed on the sticker face.</p></div>\n    <div class=\"biz-feat-card\"><h4>Bulk discount</h4><p>Lower per-sticker price as your order grows.</p></div>\n    <div class=\"biz-feat-card\"><h4>10 minimum</h4><p>Orders start at 10 stickers.</p></div>\n    <div class=\"biz-feat-card\"><h4>Dedicated support</h4><p>A real person on your account.</p></div>\n  </div>\n\n  <div id=\"biz-form-wrap\" class=\"biz-form\">\n    <h3>Tell us about your fleet</h3>\n    <p class=\"intro\">Fill this out and we'll get back to you within 1 business day with pricing tailored to your order size.</p>\n\n    <div class=\"biz-row\">\n      <label class=\"biz-label\" for=\"biz-business\">Business name *</label>\n      <input class=\"biz-input\" type=\"text\" id=\"biz-business\" maxlength=\"200\" required>\n    </div>\n    <div class=\"biz-row\">\n      <label class=\"biz-label\" for=\"biz-contact\">Your name *</label>\n      <input class=\"biz-input\" type=\"text\" id=\"biz-contact\" maxlength=\"200\" required>\n    </div>\n    <div class=\"biz-row\">\n      <label class=\"biz-label\" for=\"biz-email\">Email *</label>\n      <input class=\"biz-input\" type=\"email\" id=\"biz-email\" maxlength=\"200\" required>\n    </div>\n    <div class=\"biz-row\">\n      <label class=\"biz-label\" for=\"biz-phone\">Phone (optional)</label>\n      <input class=\"biz-input\" type=\"tel\" id=\"biz-phone\" maxlength=\"60\">\n    </div>\n    <div class=\"biz-row\">\n      <label class=\"biz-label\" for=\"biz-count\">How many stickers? * (min 10)</label>\n      <input class=\"biz-input\" type=\"number\" id=\"biz-count\" min=\"10\" max=\"100000\" value=\"10\" required>\n    </div>\n    <div class=\"biz-row\">\n      <label class=\"biz-label\">Upload your logo (optional)</label>\n      <label class=\"biz-logo-drop\" id=\"biz-drop\" for=\"biz-logo\">\n        <input type=\"file\" id=\"biz-logo\" accept=\"image/png,image/jpeg,image/webp,image/svg+xml\">\n        <p id=\"biz-drop-text\">PNG, JPG, WEBP, or SVG · max 3 MB. We'll use this to design your custom branding.</p>\n        <img id=\"biz-logo-preview\" class=\"biz-logo-preview\" alt=\"logo preview\">\n      </label>\n    </div>\n    <div class=\"biz-row\">\n      <label class=\"biz-label\" for=\"biz-msg\">Anything else? (optional)</label>\n      <textarea class=\"biz-textarea\" id=\"biz-msg\" maxlength=\"2000\" placeholder=\"Timeline, special requirements, etc.\"></textarea>\n    </div>\n\n    <button type=\"button\" class=\"biz-submit\" id=\"biz-submit-btn\" onclick=\"bizSubmit()\">Send inquiry</button>\n    <div class=\"biz-err\" id=\"biz-err\"></div>\n    <div class=\"biz-help\" style=\"margin-top:14px\">We don't display pricing publicly because every fleet is different. We'll send you a quote tailored to your order size.</div>\n  </div>\n\n  <div id=\"biz-ok-card\" class=\"biz-ok-card\">\n    <h3>Got it. Talk soon.</h3>\n    <p>We'll reply within 1 business day with a quote and next steps. Check your inbox at the email you provided. If you don't see it, look in spam or email <a href=\"mailto:support@tapmycar.io\" style=\"color:#16A34A;font-weight:700;text-decoration:none\">support@tapmycar.io</a>.</p>\n  </div>\n</div>\n\n<script>\n/* TMC_SMART_BACK */\nwindow.tmcSmartBack = function (fallback) {\n  fallback = fallback || '/';\n  try {\n    if (document.referrer) {\n      var ref = new URL(document.referrer);\n      if (ref.origin === window.location.origin) {\n        var here = window.location.pathname.replace(/\\/+$/, '');\n        var refPath = ref.pathname.replace(/\\/+$/, '');\n        if (refPath !== here) { window.history.back(); return; }\n      }\n    }\n  } catch (e) {}\n  window.location.href = fallback;\n};\n\n(function () {\n  var fileInput = document.getElementById('biz-logo');\n  var drop      = document.getElementById('biz-drop');\n  var dropText  = document.getElementById('biz-drop-text');\n  var preview   = document.getElementById('biz-logo-preview');\n  var logoData  = null;\n\n  fileInput.addEventListener('change', function (e) {\n    var f = e.target.files && e.target.files[0];\n    if (!f) return;\n    if (f.size > 3 * 1024 * 1024) {\n      document.getElementById('biz-err').textContent = 'Logo file is over 3 MB. Pick a smaller one.';\n      fileInput.value = '';\n      return;\n    }\n    document.getElementById('biz-err').textContent = '';\n    var rdr = new FileReader();\n    rdr.onload = function (ev) {\n      logoData = ev.target.result;\n      preview.src = logoData;\n      preview.style.display = 'block';\n      drop.classList.add('has-file');\n      dropText.textContent = f.name + ' (' + (f.size / 1024).toFixed(0) + ' KB) · click to change';\n    };\n    rdr.readAsDataURL(f);\n  });\n\n  window.bizSubmit = async function () {\n    var btn = document.getElementById('biz-submit-btn');\n    var err = document.getElementById('biz-err');\n    err.textContent = '';\n\n    var business = document.getElementById('biz-business').value.trim();\n    var contact  = document.getElementById('biz-contact').value.trim();\n    var email    = document.getElementById('biz-email').value.trim();\n    var phone    = document.getElementById('biz-phone').value.trim();\n    var count    = parseInt(document.getElementById('biz-count').value, 10) || 0;\n    var message  = document.getElementById('biz-msg').value.trim();\n\n    if (!business || !contact || !email) { err.textContent = 'Business name, your name, and email are required.'; return; }\n    if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)) { err.textContent = 'Please enter a valid email.'; return; }\n    if (count < 10) { err.textContent = 'Minimum order is 10 stickers.'; return; }\n\n    btn.disabled = true; btn.textContent = 'Sending…';\n    try {\n      var res = await fetch('/api/business-inquiry', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          business_name: business, contact_name: contact, email: email,\n          phone: phone, vehicle_count: count, message: message,\n          logo_data_url: logoData || ''\n        })\n      });\n      var data = await res.json();\n      if (!res.ok || !data.ok) throw new Error(data.error || 'Submit failed');\n      document.getElementById('biz-form-wrap').style.display = 'none';\n      document.getElementById('biz-ok-card').style.display = 'block';\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    } catch (e) {\n      err.textContent = e.message || 'Something went wrong. Try again or email support@tapmycar.io.';\n      btn.disabled = false; btn.textContent = 'Send inquiry';\n    }\n  };\n})();\n</script>\n</body>\n</html>\n", "api/create-checkout.js": "/* TMC_PATCH36B_CANCEL_WORDING */\nconst stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);\nconst { createClient } = require('@supabase/supabase-js');\nconst supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);\nconst { resolveUser, recordTokenType } = require('./_auth'); /* TMC_PATCH38S4 */\n\n/**\n * TapMyCar Checkout — v4.0 FINAL\n * ══════════════════════════════════════════════════════════════\n * KEY CHANGE FROM v3: We now use `mode: 'payment'` (one-time payment) instead\n * of `mode: 'subscription'`. This makes Stripe's checkout show ONLY the sticker\n * price as the hero (\"Pay $9.99\"), not the confusing \"$9.99 per year\" display.\n *\n * The recurring subscription is created AFTER payment succeeds, in the webhook,\n * using the saved card. This is the architecturally-correct way to combine\n * a one-time lifetime charge with a recurring subscription.\n *\n * Flows:\n *   etag_free   — no Stripe\n *   activate    — $1 one-time today (webhook creates subscription with 30-day trial)\n *   direct      — sticker fee one-time today (webhook creates subscription with 30-day trial)\n *   +prepay     — includes year 1 annual in today's charge; webhook uses longer trial (365 days)\n */\n\nconst ACTIVATION_FEE = 100;\nconst STICKER_PRICE = { standard: 999, premium: 2499 };\nconst ANNUAL_PRICE = { standard: 999, premium: 1999 };\n\nmodule.exports = async function handler(req, res) {\n  /* TMC_PATCH34_AUTOMATIC_TAX: per-item tax code. CT 6.35% standard rate on all items\n     for now. When CPA confirms a different SaaS rate, change the tax_code\n     on subscription/activation line items. */\n  const _STRIPE_TAX_CODE = 'txcd_99999999'; // General — Tangible Goods (standard rate)\n\n  function _withTax(item) {\n    if (item && item.price_data) {\n      item.price_data.tax_behavior = 'exclusive';\n      item.price_data.product_data = item.price_data.product_data || {};\n      item.price_data.product_data.tax_code = _STRIPE_TAX_CODE;\n    }\n    return item;\n  }\n\n  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });\n\n  // TMC_PATCH7_ACTIVATE_SMS: accept activation_session_id + token from body\n  const { activation_session_id: _tmcActSession, token: _tmcTagToken } = req.body;\n  /* TMC_PATCH38S4: identify the caller from a signed session token or a\n     legacy UUID. resolveUser() accepts both, so no logged-in user is\n     locked out; the resolved id replaces any user_id the request claimed\n     (IDOR fix). viaLegacy records which token type, for the counter. */\n  const _tmcAuth = resolveUser(req);\n  if (!_tmcAuth) return res.status(401).json({ error: 'Authentication required' });\n  const user_id = _tmcAuth.userId;\n  await recordTokenType(supabase, user_id, _tmcAuth.viaLegacy);\n\n  const { flow, plan, prepay, referral_discount } = req.body;\n  if (!flow) return res.status(400).json({ error: \"flow required: 'etag_free', 'activate', or 'direct'\" });\n\n  const { data: user } = await supabase.from('users').select('*').eq('id', user_id).single();\n  if (!user) return res.status(404).json({ error: 'User not found' });\n\n  // Prevent duplicate purchases (e.g. Standard user trying to buy Standard again)\n  if (flow === 'direct' && user.plan === plan) {\n    return res.status(400).json({\n      error: `You're already on the ${plan.charAt(0).toUpperCase() + plan.slice(1)} plan.`\n    });\n  }\n\n  // TMC_PATCH28_EXISTING_SUB_GUARD: stronger existing-subscription guard.\n  // If the user has a subscription_id, ask Stripe whether it's still active.\n  // Active/trialing -> refuse new checkout (prevents Vishnu-style double-pay).\n  // Canceled/incomplete_expired/past_due -> allow (user is re-subscribing).\n  if ((flow === 'activate' || flow === 'direct') && user.subscription_id) {\n    try {\n      const existingSub = await stripe.subscriptions.retrieve(user.subscription_id);\n      const blockingStatuses = ['active', 'trialing', 'past_due', 'unpaid'];\n      if (existingSub && blockingStatuses.indexOf(existingSub.status) >= 0) {\n        return res.status(400).json({\n          error: 'You already have an active subscription. Manage it in your dashboard.',\n          code: 'existing_subscription',\n          subscription_status: existingSub.status,\n          dashboard_url: '/dashboard.html'\n        });\n      }\n      // Otherwise (canceled, incomplete_expired): fall through and allow new checkout.\n    } catch (subErr) {\n      // If Stripe says \"no such subscription\" (id stale), allow checkout.\n      // For any other error, log but don't block — we don't want a Stripe\n      // outage to lock the user out of paying.\n      if (subErr && subErr.code !== 'resource_missing') {\n        console.warn('existing-sub check failed (continuing):', subErr.message);\n      }\n    }\n  }\n\n  // ─── FLOW 1: Free eTag ─────────────────────────────────────────\n  if (flow === 'etag_free') {\n    const { data: tag } = await supabase.from('tags').select('*').eq('owner_id', user_id).eq('status', 'unclaimed').single();\n    if (tag) {\n      await supabase.from('tags').update({ status: 'claimed', plan: 'etag' }).eq('id', tag.id);\n    }\n    return res.json({ success: true, redirect: '/etag.html', free: true });\n  }\n\n  /* TMC_PATCH35DRENEWFIX2_WHITELIST: allow the renew flow past the whitelist guard */\n  /* TMC_PATCH36UPGRADE_STD_TO_PREMIUM: allow upgrade flow */\n  if (flow !== 'activate' && flow !== 'direct' && flow !== 'renew' && flow !== 'upgrade') {\n    return res.status(400).json({ error: `Invalid flow '${flow}'` });\n  }\n  if (plan !== 'standard' && plan !== 'premium') {\n    return res.status(400).json({ error: `Invalid plan '${plan}'` });\n  }\n\n  const STICKER = STICKER_PRICE[plan];\n  const ANNUAL = ANNUAL_PRICE[plan];\n  const SUB_PRICE_ID = plan === 'standard' ? process.env.STRIPE_STANDARD_PRICE_ID : process.env.STRIPE_PREMIUM_PRICE_ID;\n\n  if (!SUB_PRICE_ID) {\n    return res.status(500).json({ error: `Missing STRIPE_${plan.toUpperCase()}_PRICE_ID env var` });\n  }\n\n  try {\n    // Get/create Stripe customer\n    let customerId = user.stripe_customer_id;\n    if (!customerId) {\n      const customer = await stripe.customers.create({\n        email: user.email || undefined,\n        name: user.name || undefined,\n        metadata: { user_id }\n      });\n      customerId = customer.id;\n      await supabase.from('users').update({ stripe_customer_id: customerId }).eq('id', user_id);\n    }\n\n    // ─── Build one-time payment line items based on flow+plan+prepay ───\n    const lineItems = [];\n    let chargeTodayCents = 0;\n\n    if (flow === 'activate') {\n      // $1 activation fee\n      lineItems.push(_withTax({\n        price_data: {\n          currency: 'usd',\n          product_data: {\n            name: 'TapMyCar tag activation',\n            description: `$1 activates your tag for 30 days. On day 30 we'll ship your ${plan === 'standard' ? 'Standard' : 'Premium'} sticker and charge ${plan === 'standard' ? '$9.99' : '$24.99'}. On day 60 your annual plan begins at ${plan === 'standard' ? '$9.99' : '$19.99'}/year.`\n          },\n          unit_amount: ACTIVATION_FEE\n        },\n        quantity: 1\n      }));\n      chargeTodayCents += ACTIVATION_FEE;\n\n      if (prepay) {\n        // Bundle sticker + year 1 into today's charge\n        lineItems.push(_withTax({\n          price_data: {\n            currency: 'usd',\n            product_data: {\n              name: plan === 'standard' ? 'Standard sticker (lifetime)' : 'Premium 3 stickers (lifetime)'\n            },\n            unit_amount: STICKER\n          },\n          quantity: 1\n        }));\n        lineItems.push(_withTax({\n          price_data: {\n            currency: 'usd',\n            product_data: { name: `Year 1 ${plan === 'standard' ? 'Standard' : 'Premium'} annual subscription` },\n            unit_amount: ANNUAL\n          },\n          quantity: 1\n        }));\n        chargeTodayCents += STICKER + ANNUAL;\n      }\n    }\n\n    /* TMC_PATCH35DRENEW_GIFT_RENEWAL: renewal flow — annual fee ONLY, no sticker, no shipping.\n       The gift recipient already has the sticker; this just pays for the\n       year of service and reactivates their tag. */\n    /* TMC_UPGRADE_FLAT_1499: Standard -> Premium upgrade. Single flat $14.99\n       line item that covers 2 extra stickers + Premium features upgrade.\n       The new Premium $19.99/yr subscription is created in the webhook on\n       payment success, replacing the old Standard $9.99/yr sub. */\n    if (flow === 'upgrade') {\n      lineItems.push(_withTax({\n        price_data: {\n          currency: 'usd',\n          product_data: {\n            name: 'TapMyCar Premium upgrade',\n            description: '2 additional weatherproof NFC + QR stickers ship in 2-3 business days. Your annual plan changes to Premium ($19.99/yr) starting next renewal. Refundable within 14 days minus the $1 service fee.'\n          },\n          unit_amount: 1499\n        },\n        quantity: 1\n      }));\n      chargeTodayCents += 1499;\n    }\n\n    if (flow === 'renew') {\n      lineItems.push(_withTax({\n        price_data: {\n          currency: 'usd',\n          product_data: {\n            name: plan === 'standard'\n              ? 'TapMyCar Standard — annual plan (reactivate your tag)'\n              : 'TapMyCar Premium — annual plan (reactivate your tag)',\n            description: 'Renews your TapMyCar service for one year and reactivates the tag you already have. Not satisfied? Request a refund within 14 days — a $1 service fee is retained. After 14 days, the plan is non-refundable.'\n          },\n          unit_amount: ANNUAL\n        },\n        quantity: 1\n      }));\n      chargeTodayCents += ANNUAL;\n    }\n\n    if (flow === 'direct') {\n      // Sticker fee today\n      lineItems.push(_withTax({\n        price_data: {\n          currency: 'usd',\n          product_data: {\n            name: plan === 'standard'\n              ? 'TapMyCar Standard — 1 physical NFC + QR sticker (lifetime)'\n              : 'TapMyCar Premium — 3 physical NFC + QR stickers (lifetime, for family)',\n            description: plan === 'standard'\n              ? `Ships in 2-3 business days. On day 30, your $9.99/year annual plan begins. Request a refund within 14 days — a $1 service fee is retained; non-refundable after that.`\n              : `Ships in 2-3 business days. Comes with 3 gift codes to share with family. On day 30, your $19.99/year annual plan begins. Request a refund within 14 days — a $1 service fee is retained; non-refundable after that.`\n          },\n          unit_amount: STICKER\n        },\n        quantity: 1\n      }));\n      chargeTodayCents += STICKER;\n\n      if (prepay) {\n        lineItems.push(_withTax({\n          price_data: {\n            currency: 'usd',\n            product_data: { name: `Year 1 ${plan === 'standard' ? 'Standard' : 'Premium'} annual subscription` },\n            unit_amount: ANNUAL\n          },\n          quantity: 1\n        }));\n        chargeTodayCents += ANNUAL;\n      }\n    }\n\n    /* TMC_PATCH45B: server-side referral credit. The client may pass\n       apply_referral_credit:true/false; the *amount* is recomputed here\n       from the referrals table  the client cannot inflate it. Credits\n       are spent in FIFO order; we collect the row ids so the webhook (or\n       the free-flow branch below) can mark them consumed atomically. */\n    const applyCredit = req.body.apply_referral_credit !== false; /* default ON */\n    let _tmcCreditCents = 0;\n    let _tmcCreditRowIds = [];\n    if (applyCredit) {\n      /* TMC_PATCH46_FIX2: stop collecting at the amount we could possibly\n         use for this transaction. Without this, a $9.99 renewal would\n         consume $12 of credit (all 4 rows) because the consume step\n         flips every collected row.\n         maxApply mirrors the math used below the loop. */\n      const _tmcFullCover  = (flow === 'renew' || flow === 'upgrade');\n      const _tmcMaxApply   = _tmcFullCover ? chargeTodayCents : Math.max(0, chargeTodayCents - 100);\n      const nowIso = new Date().toISOString();\n      const { data: avRows } = await supabase\n        .from('referrals')\n        .select('id, credit_amount, status, available_at, credit_kind')\n        .eq('referrer_user_id', user_id)\n        .in('status', ['pending','available'])\n        .order('paid_at', { ascending: true });\n      /* TMC_PATCH51A: renewal_only credits are filtered OUT unless flow\n         is renew. General (default) credits work on anything. */\n      const _tmcIsRenew = (flow === 'renew');\n      const usable = (avRows || []).filter(r => {\n        const okStatus = r.status === 'available' ||\n          (r.status === 'pending' && r.available_at && r.available_at <= nowIso);\n        if (!okStatus) return false;\n        const kind = r.credit_kind || 'general';\n        if (kind === 'renewal_only' && !_tmcIsRenew) return false;\n        return true;\n      });\n      for (const r of usable) {\n        if (_tmcCreditCents >= _tmcMaxApply) break;\n        _tmcCreditCents += Math.round((parseFloat(r.credit_amount) || 0) * 100);\n        _tmcCreditRowIds.push(r.id);\n      }\n    }\n\n    /* Apply the credit to the first line item (the dominant charge). The\n       $1 floor is needed for activate/direct flows so Stripe has a real\n       charge to attach the card to; renew/upgrade can go to $0 (handled\n       in the free-flow branch below). */\n    let _tmcCreditUsedCents = 0;\n    if (_tmcCreditCents > 0 && lineItems.length > 0 && lineItems[0].price_data) {\n      const firstUnit = lineItems[0].price_data.unit_amount;\n      const fullCoverFlows = (flow === 'renew' || flow === 'upgrade');\n      const maxApply = fullCoverFlows ? chargeTodayCents : Math.max(0, chargeTodayCents - 100);\n      _tmcCreditUsedCents = Math.min(_tmcCreditCents, maxApply);\n      if (_tmcCreditUsedCents > 0) {\n        /* distribute across line items so each unit_amount stays >= 0 */\n        let remaining = _tmcCreditUsedCents;\n        for (const li of lineItems) {\n          if (remaining <= 0) break;\n          if (!li.price_data) continue;\n          const take = Math.min(remaining, li.price_data.unit_amount);\n          li.price_data.unit_amount -= take;\n          remaining -= take;\n        }\n        chargeTodayCents -= _tmcCreditUsedCents;\n      }\n    }\n\n    /* FREE-FLOW BRANCH: credit covers the whole price AND the flow is one\n       where we don't need a new card on file (renew/upgrade). Skip Stripe\n       entirely, run the side-effects inline, mark credits consumed. */\n    if (chargeTodayCents === 0 && (flow === 'renew' || flow === 'upgrade')) {\n      try {\n        if (flow === 'renew') {\n          /* mirror the webhook's 'renew' side-effects: subscription create\n             (paid today => trial 365d so first cycle bills a year out),\n             user plan restore, reactivate gift tag(s), record order. */\n          let renewSub = null;\n          try {\n            renewSub = await stripe.subscriptions.create({\n              customer: customerId,\n              items: [{ price: SUB_PRICE_ID }],\n              trial_period_days: 365,\n              metadata: { user_id, plan, flow: 'renew', referral_credit_applied: String(_tmcCreditUsedCents) }\n            });\n          } catch (e) {\n            console.error('p45b free renew: sub create failed:', e.message);\n          }\n          await supabase.from('users').update({\n            plan,\n            subscription_id: renewSub ? renewSub.id : null,\n            gift_expired_at: null,\n            gift_reminders_sent: ''\n          }).eq('id', user_id);\n          await supabase.from('tags').update({\n            status: 'active',\n            gift_expired: false\n          }).eq('owner_id', user_id).eq('is_gift', true);\n          await supabase.from('orders').insert({\n            user_id, plan,\n            amount: 0,\n            stripe_id: 'credit_only_' + Date.now(),\n            subscription_id: renewSub ? renewSub.id : null,\n            status: 'paid',\n            sticker_count: 0,\n            order_status: 'renewal'\n          });\n        } else if (flow === 'upgrade') {\n          /* upgrade STD -> Premium fully covered by credit. Flip plan,\n             generate 3 Premium codes, claim the first to the buyer,\n             record an order. We don't modify the existing subscription's\n             price here  that's a follow-up the user's annual renewal\n             will pick up. */\n          await supabase.from('users').update({ plan: 'premium' }).eq('id', user_id);\n          const generatePremiumCode = function () {\n            const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n            let code = 'TMC-PREM-';\n            for (let i = 0; i < 6; i++) code += chars[Math.floor(Math.random() * chars.length)];\n            return code;\n          };\n          const { data: orderRow } = await supabase.from('orders').insert({\n            user_id, plan: 'premium',\n            amount: 0,\n            stripe_id: 'credit_only_' + Date.now(),\n            subscription_id: user.subscription_id || null,\n            status: 'paid',\n            sticker_count: 2,\n            order_status: 'upgrade'\n          }).select().single();\n          const premiumCodes = [];\n          if (orderRow) {\n            for (let i = 0; i < 3; i++) {\n              let code = generatePremiumCode();\n              for (let a = 0; a < 5; a++) {\n                const { data: ex } = await supabase.from('premium_codes').select('id').eq('code', code).maybeSingle();\n                if (!ex) break;\n                code = generatePremiumCode();\n              }\n              const { data: cr } = await supabase.from('premium_codes').insert({\n                code, buyer_user_id: user_id, buyer_order_id: orderRow.id\n              }).select().single();\n              if (cr) premiumCodes.push(cr.code);\n            }\n            if (premiumCodes.length > 0) {\n              await supabase.from('premium_codes')\n                .update({ redeemed_by_user_id: user_id, redeemed_at: new Date().toISOString() })\n                .eq('code', premiumCodes[0]);\n              await supabase.from('users').update({ redeemed_code: premiumCodes[0] }).eq('id', user_id);\n            }\n          }\n        }\n        /* TMC_PATCH46_FIX3: split-last-row consumption. _tmcCreditCents\n           is what we COLLECTED, _tmcCreditUsedCents is what was actually\n           APPLIED. The difference is leftover that must come back to the\n           user as a new 'available' row. Without this, a $9.99 renewal\n           that collects 4x$3 rows ($12) would burn all $12 even though\n           only $9.99 was needed.\n           Mark all collected rows consumed (clean audit trail), then\n           insert a fresh 'available' row for the leftover amount. */\n        if (_tmcCreditRowIds.length > 0) {\n          await supabase.from('referrals').update({\n            status: 'consumed',\n            consumed_at: new Date().toISOString()\n          }).in('id', _tmcCreditRowIds);\n          const _tmcLeftoverCents = _tmcCreditCents - _tmcCreditUsedCents;\n          if (_tmcLeftoverCents > 0) {\n            const leftoverDollars = (_tmcLeftoverCents / 100).toFixed(2);\n            await supabase.from('referrals').insert({\n              referrer_user_id: user_id,\n              referred_user_id: null,\n              referral_code:    'LEFTOVER',\n              status:           'available',\n              credit_amount:    parseFloat(leftoverDollars),\n              /* paid_at is required for FIFO ordering; use now so this\n                 leftover gets used LAST among future purchases (we want\n                 older real referral rows to be spent first). Wait, \n                 actually FIFO order='asc' means OLDEST paid_at first, so\n                 setting paid_at=now makes this the youngest = last. */\n              paid_at:          new Date().toISOString(),\n              available_at:     new Date().toISOString(),\n              applied_at:       new Date().toISOString()\n            });\n          }\n        }\n        return res.json({\n          free: true,\n          redirect: '/payment-success.html?free=1&plan=' + plan + '&flow=' + flow,\n          credit_used_cents: _tmcCreditUsedCents\n        });\n      } catch (e) {\n        console.error('p45b free-flow failed:', e && e.message);\n        return res.status(500).json({ error: 'Could not complete the free purchase. Please try again or contact support.' });\n      }\n    }\n\n    // ─── ONE-TIME PAYMENT MODE (not subscription!) ───────────────\n    // This is the critical change: Stripe shows \"Pay $9.99\" cleanly, not \"$9.99 per year\".\n    // The subscription is created by the webhook after payment succeeds.\n    const sessionParams = {\n      mode: 'payment',\n      customer: customerId,\n      payment_method_types: ['card'],\n      line_items: lineItems,\n      payment_intent_data: {\n        // Save the card to the customer so the webhook can create a subscription later\n        setup_future_usage: 'off_session'\n      },\n      /* TMC_PATCH35DRENEW_GIFT_RENEWAL: renew flow ships nothing — skip shipping address */\n      ...(flow === 'renew' ? {} : { shipping_address_collection: { allowed_countries: ['US'] } }),\n      billing_address_collection: 'required',\n      /* TMC_PATCH34_AUTOMATIC_TAX: Stripe Tax — calculates tax based on shipping address */\n      automatic_tax: { enabled: true },\n      customer_update: { address: 'auto', shipping: 'auto', name: 'auto' },\n      metadata: {\n        user_id,\n        plan,\n        flow,\n        // TMC_PATCH7_ACTIVATE_SMS: pass through to webhook for activation gate\n        activation_session_id: _tmcActSession || '',\n        tag_token: _tmcTagToken || '',\n        prepay: prepay ? 'true' : 'false',\n        charge_today_cents: String(chargeTodayCents),\n        sticker_count: plan === 'premium' ? '3' : '1',\n        subscription_price_id: SUB_PRICE_ID,\n        referral_discount: String(referral_discount || 0),\n        /* TMC_PATCH45B: webhook uses these to mark credits consumed after payment. */\n        referral_credit_applied: String(_tmcCreditUsedCents || 0),\n        referral_credit_row_ids: (_tmcCreditRowIds || []).join(',')\n      },\n      success_url: `https://tapmycar.io/payment-success.html?session_id={CHECKOUT_SESSION_ID}&plan=${plan}&flow=${flow}${prepay ? '&prepay=1' : ''}`,\n      cancel_url: `https://tapmycar.io/pricing.html`\n    };\n\n    const session = await stripe.checkout.sessions.create(sessionParams);\n    return res.json({ url: session.url, charge_today_cents: chargeTodayCents });\n\n  } catch (err) {\n    console.error('create-checkout error:', err.message);\n    return res.status(500).json({ error: err.message });\n  }\n};\n", "api/business-inquiry.js": "// TMC_BUSINESS_INQUIRY: handle fleet/business contact form submissions.\nconst { createClient } = require(\"@supabase/supabase-js\");\nconst { Resend } = require(\"resend\");\nconst supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);\nconst resend = new Resend(process.env.RESEND_API_KEY);\nconst { rateLimit, getClientIp } = require('./_rate-limit');\n\nmodule.exports = async function handler(req, res) {\n  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });\n\n  const ip = getClientIp(req);\n  if (!await rateLimit(req, res, [{ key: 'biz-inq:ip:' + ip, max: 3, windowSeconds: 3600 }])) return;\n\n  const b = req.body || {};\n  const business_name  = String(b.business_name || '').trim().slice(0, 200);\n  const contact_name   = String(b.contact_name  || '').trim().slice(0, 200);\n  const email          = String(b.email         || '').trim().toLowerCase().slice(0, 200);\n  const phone          = String(b.phone         || '').trim().slice(0, 60);\n  const vehicle_count  = parseInt(b.vehicle_count || '0', 10) || 0;\n  const message        = String(b.message       || '').trim().slice(0, 2000);\n  const logo_data_url  = String(b.logo_data_url || '');\n\n  if (!business_name || !contact_name || !email)\n    return res.status(400).json({ error: 'business_name, contact_name and email are required' });\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email))\n    return res.status(400).json({ error: 'Invalid email' });\n  if (vehicle_count < 10)\n    return res.status(400).json({ error: 'Minimum order is 10 stickers' });\n\n  // Optional logo upload  store in videos bucket under logos/ subfolder.\n  let logo_url = null;\n  if (logo_data_url && logo_data_url.startsWith('data:image/')) {\n    try {\n      const match = logo_data_url.match(/^data:(image\\/[a-z+]+);base64,(.+)$/i);\n      if (match) {\n        const mime = match[1];\n        const ext  = mime.split('/')[1].replace('+xml', '').replace('jpeg', 'jpg');\n        const buf  = Buffer.from(match[2], 'base64');\n        if (buf.length <= 3 * 1024 * 1024) { // 3 MB cap\n          const key  = 'logos/' + Date.now() + '-' + Math.random().toString(36).slice(2, 8) + '.' + ext;\n          const { error: upErr } = await supabase.storage.from('videos').upload(key, buf, {\n            contentType: mime, upsert: false\n          });\n          if (!upErr) {\n            const base = (process.env.SUPABASE_URL || '').replace(/\\/$/, '') + '/storage/v1/object/public/videos/';\n            logo_url = base + key;\n          }\n        }\n      }\n    } catch (e) { console.error('logo upload failed:', e && e.message); }\n  }\n\n  // Persist (best-effort; tolerate table absence so the email still goes out).\n  try {\n    await supabase.from('business_leads').insert({\n      business_name, contact_name, email, phone, vehicle_count, message, logo_url, status: 'new'\n    });\n  } catch (e) { console.error('business_leads insert failed:', e && e.message); }\n\n  // Email to support\n  try {\n    const html =\n      '<div style=\"font-family:Inter,Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px\">' +\n      '<h2 style=\"color:#FF6B00;margin:0 0 16px\">New Business / Fleet inquiry</h2>' +\n      '<div style=\"background:#F9FAFB;border:1px solid #E5E7EB;border-radius:12px;padding:16px;font-size:14px;color:#111;line-height:1.7\">' +\n        '<b>Business:</b> ' + business_name + '<br>' +\n        '<b>Contact:</b> ' + contact_name + '<br>' +\n        '<b>Email:</b> <a href=\"mailto:' + email + '\">' + email + '</a><br>' +\n        (phone ? '<b>Phone:</b> ' + phone + '<br>' : '') +\n        '<b>Vehicles / stickers:</b> ' + vehicle_count + '<br>' +\n        (logo_url ? '<b>Logo:</b> <a href=\"' + logo_url + '\">' + logo_url + '</a><br>' : '<b>Logo:</b> (none uploaded)<br>') +\n      '</div>' +\n      (message ? '<div style=\"margin-top:14px;background:#FFF7ED;border:1px solid #FED7AA;border-radius:12px;padding:14px;font-size:13px;color:#7C2D12;line-height:1.6\"><b>Message:</b><br>' + message.replace(/</g,'&lt;').replace(/\\n/g,'<br>') + '</div>' : '') +\n      (logo_url ? '<div style=\"margin-top:14px\"><img src=\"' + logo_url + '\" alt=\"logo\" style=\"max-width:240px;max-height:240px;border-radius:8px;border:1px solid #E5E7EB\"></div>' : '') +\n      '</div>';\n    await resend.emails.send({\n      from: 'TapMyCar <noreply@tapmycar.io>',\n      to: 'support@tapmycar.io',\n      reply_to: email,\n      subject: 'Business / Fleet inquiry: ' + business_name + ' (' + vehicle_count + ' stickers)',\n      html\n    });\n  } catch (e) { console.error('inquiry email send failed:', e && e.message); }\n\n  return res.json({ ok: true });\n};\n"};

const MARKERS = {"public/pricing.html": "TMC_PRICING_REFRESH", "public/landing.html": "TMC_LAND_OBJECTIONS", "public/manage.html": "TMC_UPGRADE_CONFIRM", "public/help.html": "TMC_FAQ_UPGRADE_PRICE", "public/business.html": "TMC_BUSINESS_INQUIRY", "api/create-checkout.js": "TMC_UPGRADE_FLAT_1499", "api/business-inquiry.js": "TMC_BUSINESS_INQUIRY"};

let touched = 0;
for (const fp of Object.keys(FILES)) {
  const cur = fs.existsSync(fp) ? fs.readFileSync(fp, 'utf8') : '';
  if (cur.indexOf(MARKERS[fp]) !== -1) {
    console.log(fp + ': skip (already patched)');
    continue;
  }
  fs.mkdirSync(path.join(BACKUP_DIR, path.dirname(fp)), { recursive: true });
  if (fs.existsSync(fp)) fs.copyFileSync(fp, path.join(BACKUP_DIR, fp));
  fs.writeFileSync(fp, FILES[fp], 'utf8');
  if (fp.endsWith('.js')) {
    try { require('child_process').execSync('node --check "' + fp + '"', { stdio: 'pipe' }); }
    catch (e) { throw new Error(fp + ': node --check failed: ' + String(e.stderr || e.message)); }
  }
  console.log(fp + ': written');
  touched++;
}

console.log('');
if (touched === 0) {
  console.log('Nothing to do  already patched.');
} else {
  console.log('Done. ' + touched + ' file(s) written. Backups in ' + BACKUP_DIR + '/');
  console.log('');
  console.log('FIRST: in Supabase SQL editor, run patch-business-leads-migration.sql');
  console.log('');
  console.log('NEXT STEPS:');
  console.log('  git add -A');
  console.log('  git commit -m "Pricing copy + $14.99 upgrade + Business page + Landing additions"');
  console.log('  git push');
}
